        "apitest",
        "cypress",
        "espresso",
        "imagerunner",
        "playwright",
        "puppeteer-replay",
        "testcafe",
        "xcuitest",
        "playwright-cucumberjs"
      ]
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
