          "kind",
          "suites"
        ],
        "additionalProperties": true
      }
    }
  ]
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "default": {
    "IsEncrypted": false,
    "Values": {
      "AzureWebJobsStorage": "",
      "FUNCTIONS_WORKER_RUNTIME": ""
    }
  },
  "id": "https://json.schemastore.org/local.settings.json",
  "properties": {
    "IsEncrypted": {
      "type": "boolean",
      "description": "When this setting is set to true, all values are encrypted with a local machine key. Used with func settings commands. Default value is false. You might want to encrypt the local.settings.json file on your local computer when it contains secrets, such as service connection strings. The host automatically decrypts settings when it runs. Use the func settings decrypt command before trying to read locally encrypted settings.",
      "default": false
    },
    "Values": {
      "type": "object",
      "description": "Application settings and connection strings used when a project is running locally. These key-value (string-string) pairs correspond to application settings in your function app in Azure, like AzureWebJobsStorage. Many triggers and bindings have a property that refers to a connection string app setting, like Connection for the Blob storage trigger. For these properties, you need an application setting defined in the Values array. See the subsequent table for a list of commonly used settings. Values must be strings and not JSON objects or arrays. Setting names can't include a colon (:) or a double underline (__). Double underline characters are reserved by the runtime, and the colon is reserved to support dependency injection.",
      "properties": {
        "FUNCTIONS_WORKER_RUNTIME": {
          "type": "string",
          "enum": [
            "custom",
            "dotnet",
            "dotnet-isolated",
            "node",
            "java",
            "powershell",
            "python"
          ],
          "description": "Indicates the targeted language of the Functions runtime. Required for version 2.x and higher of the Functions runtime. This setting is generated for your project by Core Tools. To learn more, see the FUNCTIONS_WORKER_RUNTIME reference."
        },
        "AzureWebJobsStorage": {
          "type": "string",
          "description": "Contains the connection string for an Azure storage account. Required when using triggers other than HTTP. For more information, see the AzureWebJobsStorage reference. When you have the Azure storage emulator installed locally and you set AzureWebJobsStorage to UseDevelopmentStorage=true, Core Tools uses the emulator. The emulator is useful during development, but you should test with an actual storage connection before deployment.",
          "examples": ["", "UseDevelopmentStorage=true"]
        },
        "AzureWebJobsDashboard": {
          "type": "string",
          "description": "DEPRECATED. Legacy Storage connection string for storing logs. May impact performance and increase Storage transactions/costs."
        },
        "FUNCTIONS_WORKER_RUNTIME_VERSION": {
          "type": "string",
          "description": "Indicates that PowerShell 7 be used when running locally. If not set, then PowerShell Core 6 is used. This setting is only used when running locally. When running in Azure, the PowerShell runtime version is determined by the powerShellVersion site configuration setting, which can be set in the portal."
        }
      }
    },
    "Host": {
      "type": "object",
      "description": "Settings in this section customize the Functions host process when you run projects locally. These settings are separate from the host.json settings, which also apply when you run projects in Azure.",
      "properties": {
        "LocalHttpPort": {
          "type": "integer",
          "description": "Settings in this section customize the Functions host process when you run projects locally. These settings are separate from the host.json settings, which also apply when you run projects in Azure."
        },
        "CORS": {
          "type": "string",
          "description": "Defines the origins allowed for cross-origin resource sharing (CORS). Origins are supplied as a comma-separated list with no spaces. The wildcard value (*) is supported, which allows requests from any origin."
        },
        "CORSCredentials": {
          "type": "boolean",
          "description": "When set to true, allows withCredentials requests."
        }
      }
    },
    "ConnectionStrings": {
      "type": "object",
      "description": "A collection. Don't use this collection for the connection strings used by your function bindings. This collection is used only by frameworks that typically get connection strings from the ConnectionStrings section of a configuration file, like Entity Framework. Connection strings in this object are added to the environment with the provider type of System.Data.SqlClient. Items in this collection aren't published to Azure with other app settings. You must explicitly add these values to the Connection strings collection of your function app settings. If you're creating a SqlConnection in your function code, you should store the connection string value with your other connections in Application Settings in the portal."
    }
  },
  "title": "JSON schema for Azure Functions local.settings.json files",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/drupal-info.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "allOf": [
    {
      "if": {
        "properties": {
          "type": {
            "const": "module"
          }
        }
      },
      "then": {
        "properties": {
          "configure": {
            "title": "A route name of the configuration form",
            "type": "string"
          },
          "dependencies": {
            "type": "array",
            "items": {
              "$ref": "#/definitions/dependency"
            }
          },
          "test_dependencies": {
            "title": "Dependencies that are needed to run certain automated tests for this extension",
            "type": "array",
            "items": {
              "$ref": "#/definitions/dependency"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "type": {
            "const": "theme"
          }
        }
      },
      "then": {
        "properties": {
          "base theme": {
            "title": "Base theme",
            "default": "classy",
            "oneOf": [
              {
                "type": "string"
              },
              {
                "type": "boolean"
              }
            ]
          },
          "libraries": {
            "title": "A list of libraries to add to all pages where the theme is active",
            "type": "array",
            "items": {
              "type": "string",
              "pattern": "^[a-z0-9_]+/[a-z0-9_\\-.]+$"
            }
          },
          "libraries-override": {
            "title": "A collection of libraries and assets to override",
            "type": "object",
            "additionalProperties": {
              "oneOf": [
                {
                  "type": "object"
                },
                {
                  "type": "string"
                },
                {
                  "type": "boolean"
                }
              ]
            }
          },
          "libraries-extend": {
            "title": "A collection of libraries and assets to add whenever a library is attached",
            "type": "object",
            "additionalProperties": {
              "type": "array"
            }
          },
          "engine": {
            "title": "The theme engine",
            "default": "twig",
            "type": "string"
          },
          "logo": {
            "title": "The path to logo relative to the theme's .info.yml",
            "type": "string"
          },
          "screenshot": {
            "title": "The path to screenshot relative to the theme's .info.yml file",
            "type": "string"
          },
          "regions": {
            "title": "A list of theme regions",
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          },
          "regions_hidden": {
            "title": "A list of inherited regions to remove",
            "type": "array",
            "uniqueItems": true
          },
          "features": {
            "title": "A list of features to expose on the theme 'Settings' page",
            "type": "array",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "stylesheets-remove": {
            "title": "A list of stylesheets from other modules or themes to remove from all pages where the theme is active",
            "type": "array",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "ckeditor_stylesheets": {
            "title": "A list of stylesheets to add to the CKEditor frame",
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "type": {
            "const": "profile"
          }
        }
      },
      "then": {
        "properties": {
          "distribution": {
            "title": "Declare the installation profile as a distribution",
            "type": "object",
            "properties": {
              "name": {
                "title": "The distribution name",
                "type": "string"
              },
              "install": {
                "type": "object",
                "properties": {
                  "theme": {
                    "title": "The theme for the distribution installation",
                    "$ref": "#/definitions/machine_name"
                  }
                }
              },
              "langcode": {
                "type": "string"
              }
            }
          },
          "dependencies": {
            "title": "Required modules",
            "type": "array",
            "items": {
              "$ref": "#/definitions/machine_name"
            },
            "uniqueItems": true
          },
          "install": {
            "title": "Modules to install to support the profile",
            "type": "array",
            "items": {
              "$ref": "#/definitions/dependency"
            },
            "uniqueItems": true
          },
          "theme": {
            "title": "List any themes that should be installed as part of the profile installation",
            "type": "array",
            "items": {
              "$ref": "#/definitions/machine_name"
            },
            "uniqueItems": true
          }
        }
      }
    }
  ],
  "definitions": {
    "dependency": {
      "title": "Extension dependency",
      "type": "string",
      "pattern": "^[a-z0-9_]+:[a-z0-9_]+( \\(.+\\))?$"
    },
    "machine_name": {
      "title": "Machine name",
      "type": "string",
      "pattern": "^[a-z0-9_]+$"
    }
  },
  "properties": {
    "name": {
      "title": "The human-readable name",
      "type": "string"
    },
    "type": {
      "type": "string",
      "enum": ["module", "theme", "profile", "theme_engine"]
    },
    "core": {
      "type": "string",
      "pattern": "^\\d\\.x$"
    },
    "core_version_requirement": {
      "title": "Semantic core version requirement",
      "type": "string"
    },
    "description": {
      "title": "Extension description",
      "type": "string"
    },
    "package": {
      "title": "A key that allows to group extension together an administrative pages",
      "type": "string"
    },
    "version": {
      "title": "The version of the extension",
      "type": "string"
    },
    "project": {
      "title": "The machine name of extension project on drupal.org",
      "type": "string"
    },
    "datestamp": {
      "title": "The date and time when the extension was packaged",
      "type": "integer"
    },
    "hidden": {
      "title": "Do not the extension in admin interface",
      "type": "boolean"
    },
    "php": {
      "title": "The minimal PHP version that is required for this extension",
      "oneOf": [
        {
          "type": "string",
          "pattern": "^\\d+\\.\\d+(\\.\\d+)$"
        },
        {
          "type": "number"
        }
      ]
    }
  },
  "required": ["type", "core_version_requirement", "name"],
  "title": "JSON schema for Drupal extension info file",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": true,
  "definitions": {
    "engineOptions": {
      "type": "object",
      "description": "The options to configure the chosen browser engine for Chutzpah to use.",
      "properties": {
        "ChromeBrowserPath": {
          "description": "The path to the chrome/chromium executable on the machine",
          "type": "string"
        }
      }
    },
    "serverSettings": {
      "description": "Server settings let you enable to configure Chutzpah web server mode.",
      "type": "object",
      "properties": {
        "Enabled": {
          "description": "Determines if the web server mode is enabled.",
          "type": "boolean",
          "default": false
        },
        "DefaultPort": {
          "description": "The default port to use. If this port is taken Chutzpah will try incrementing until it finds an available one.",
          "type": "number"
        },
        "RootPath": {
          "description": "The root path of the server. All file paths are relative to this and should be in a directory below or equal to this. Defaults to drive root.",
          "type": "string"
        }
      }
    },
    "templateOptions": {
      "properties": {
        "Mode": {
          "description": "The way the template is injected into the HTML page.",
          "enum": ["Raw", "Script"],
          "default": "Raw"
        },
        "Id": {
          "description": "If in script mode what Id to place on the script tag.",
          "type": "string"
        },
        "Type": {
          "description": "If in script mode what Type to place on script tag",
          "type": "string"
        }
      }
    },
    "referenceSettings": {
      "properties": {
        "Path": {
          "description": "The path to either a file or a folder. If given a folder, it will be scanned recursively. This path can be relative to the location of the chutzpah.json file.",
          "type": "string"
        },
        "Includes": {
          "description": "This is an optional array of include glob patterns. Only files matching the Include pattern will be added.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "Excludes": {
          "description": "This is an optional array of exclude glob patterns.  Only files not matching the Exclude patterns will be added.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "IncludeInTestHarness": {
          "description": "This determines if the reference should be injected into the test harness. When referencing files like .d.ts or files that you plan to load using require.js you should set this to false. Defaults to true.",
          "type": "boolean",
          "default": true
        },
        "IsTestFrameworkFile": {
          "description": "Indicated that this references should be placed directly after the test framework files in the test harness. This ensures that this file is injected into the test harness before almost all other files. Defaults to false.",
          "type": "boolean",
          "default": false
        },
        "TemplateOptions": {
          "$ref": "#/definitions/templateOptions"
        }
      }
    },
    "compilePathMap": {
      "properties": {
        "SourcePath": {
          "description": "The source file/directory",
          "type": "string"
        },
        "OutputPath": {
          "description": "The file/directory that source file/directory is mapped to. Specifying a file OutputPath and a directory for SourcePath indicated the files are being concatenated into one large file",
          "type": "string"
        },
        "OutputPathType": {
          "description": "The type (file or folder) that the output path refers to. If not specified Chutzpah will try to take a best guess by assuming it is a file if it has a .js extension",
          "type": "string",
          "enum": ["File", "Folder"],
          "default": "Folder"
        }
      }
    },
    "testSettings": {
      "properties": {
        "Path": {
          "description": "The path to either a file or a folder. If given a folder, it will be scanned recursively. This path can be relative to the location of the chutzpah.json file.",
          "type": "string"
        },
        "Includes": {
          "description": "This is an optional array of include glob patterns. Only files matching the Include pattern will be added.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "Excludes": {
          "description": "This is an optional array of exclude glob patterns.  Only files not matching the Exclude patterns will be added.",
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "transformConfig": {
      "properties": {
        "Name": {
          "description": "The name of the transform to execute",
          "type": "string"
        },
        "Path": {
          "description": "The file for the transform to save its output to.",
          "type": "string"
        }
      }
    },
    "compileSettings": {
      "description": "This setting lets you describe in the Chutzpah.json file how to execute a command which can compile your source files to .js files. You tell Chutzpah what to execute and some information about what your executable does (like where to find the generated .js files). Then after running the executable Chutzpah can associate each source file with each output file to still give the nice behavior of mapping tests back to their original files.",
      "type": "object",
      "properties": {
        "Extensions": {
          "description": "The extensions of the files which are getting compiled (e.g. .ts).",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "ExtensionsWithNoOutput": {
          "description": "The extensions of files which take part in compile but have no build output. This is used for cases like TypeScript declaration files which share a .ts extension. They have .d.ts extension and are part of compilation but have no output. You must tell Chutzpah about these if you want the SkipIfUnchanged setting to work. Otherwise Chutzpah will think these are missing output.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "Paths": {
          "description": " The collection of path mapping from source directory/file to output directory/file.",
          "type": "array",
          "items": {
            "$ref": "#/definitions/compilePathMap"
          }
        },
        "WorkingDirectory": {
          "description": "This is the working directory of the process which executes the command.",
          "type": "string"
        },
        "Executable": {
          "description": "The path to an executable which Chutzpah executes to perform the batch compilation. Chutzpah will try to resolve the path relative to the settings directory. But if can't find the file there you must give it a full path.",
          "type": ["string", "null"],
          "default": null
        },
        "Arguments": {
          "description": "The arguments to pass to the command.",
          "type": ["string", "null"],
          "default": null
        },
        "Timeout": {
          "description": "How long to wait for compile to finish in milliseconds?",
          "type": "integer",
          "default": 30000
        },
        "SkipIfUnchanged": {
          "description": "Skips the execution if all files Chutzpah knows about are older than all of the output files. This is defaulted to true but if you hit issues since it is possible Chutzpah might not know about all the files your compilation is using then you can turn this off. Ideally you should tell Chutzpah about these files using the references and tests settings since this setting helps Chutzpah not need to even invoke the executable if it figures out it's not needed.",
          "type": "boolean",
          "default": true
        },
        "Mode": {
          "description": "Determines how this compile setting is used. By default it is in Executable mode where it will require you provide an executable which Chutzpah will run if it sees it finds missing .js for input file. If you set this to External then Chutzpah will ignore the Executable, Arguments settings and assume you have some external process which is compiling. In this case Chutzpah will use the SourceDirectory and OutDirectory options to try to find your .js files for the input files. If it can't find them it will trace an error but still attempt to proceed.",
          "type": "string",
          "enum": ["Executable", "External"],
          "default": "External"
        },
        "UseSourceMaps": {
          "description": "Configures whether .map files should be loaded (if available) to convert under-test JS line numbers to those of their original source files.",
          "type": "boolean",
          "default": false
        },
        "IgnoreMissingFiles": {
          "description": "Should Chutzpah ignore files it expects to find compiled. If set to true Chutzpah will log an error otherwise it will throw",
          "type": "boolean",
          "default": false
        }
      }
    }
  },
  "id": "https://json.schemastore.org/chutzpah.json",
  "properties": {
    "Framework": {
      "description": "Determines what testing framework to use. This will override the other detection methods.",
      "type": "string",
      "enum": ["qunit", "jasmine", "mocha"]
    },
    "FrameworkVersion": {
      "description": "Tells Chutzpah if it should use a different version of on of the test frameworks than the default one. Currently, the only framework this works for is Jasmine. As of the 3.1.0 release Chutzpah default to Jasmine 2.0 but if you want to use the 1.0 line for Jasmine still pass '1' for FrameworkVersion.",
      "type": "string"
    },
    "References": {
      "description": "The references setting allows you to specify which files/folders to use/scan to find references. This is useful since it replaces the need to the ///<reference comments.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/referenceSettings"
      }
    },
    "Tests": {
      "description": "The references setting allows you to specify which files/folders to use/scan to find references. This is useful since it replaces the need to the ///<reference comments.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/testSettings"
      }
    },
    "Engine": {
      "description": "The browser engine to use to run the tests. Default is Phantom but JSDOM and Chrome are available. If you choose Chrome you must have an instance of Chrome or Chromium on the machine that Chutzpah can find.",
      "type": "string",
      "enum": ["Phantom", "JSDom", "Chrome"]
    },
    "EngineOptions": {
      "$ref": "#/definitions/engineOptions"
    },
    "Server": {
      "$ref": "#/definitions/serverSettings"
    },
    "Transforms": {
      "description": "List of transformers to run after testing to generate output files",
      "type": "array",
      "items": {
        "$ref": "#/definitions/transformConfig"
      }
    },
    "Compile": {
      "$ref": "#/definitions/compileSettings"
    },
    "TestFileTimeout": {
      "description": "The time to wait for tests in a file to finish in milliseconds.",
      "type": "integer"
    },
    "TestHarnessLocationMode": {
      "description": "Determines where to place the generated html test harness files. The default mode is TestFileAdjacent which means the harness is placed in the same directory as the test file. SettingsFileAdjacent means it is placed in the same directory as the chutzpah.json file. Custom mode lets you specify a custom path to the directory.",
      "type": "string",
      "enum": ["TestFileAdjacent", "SettingsFileAdjacent", "Custom"]
    },
    "TestHarnessReferenceMode": {
      "type": "string",
      "enum": ["Normal", "AMD"]
    },
    "TestHarnessDirectory": {
      "description": "When TestHarnessLocationMode is set to Custom this is either the relative or absolute path to the directory where to place the test harness.",
      "type": "string"
    },
    "RootReferencePathMode": {
      "description": "This property determines what directory a rooted reference path refers to.",
      "type": "string",
      "enum": ["DriveRoot", "SettingsFileDirectory"],
      "default": "DriveRoot"
    },
    "CodeCoverageTimeout": {
      "description": "The timeout in milliseconds for how long to wait to instrument each file for code coverage. Defaults to 5000ms.",
      "type": "integer",
      "default": 5000
    },
    "CodeCoverageExecutionMode": {
      "description": "If Always, forces code coverage to run always. If Manual/null/not set, allows code coverage to run if invoked using test adapter, command line or context menu options (default). If Never, forces code coverage to never run.",
      "type": "string",
      "enum": ["Manual", "Always", "Never"]
    },
    "CodeCoverageSuccessPercentage": {
      "description": "The percentage of lines needing to be covered to show the coverage output as success or failure. By default this is 60.",
      "type": "number"
    },
    "CodeCoverageIncludes": {
      "description": "The collection code coverage file patterns to include in coverage. These are in glob format. If you specify none all files are included.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "CodeCoverageExcludes": {
      "description": "The collection code coverage file patterns to exclude in coverage. These are in glob format. If you specify none no files are excluded.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "CustomTestHarnessPath": {
      "description": "The CustomTestHarnessPath setting allows you to override the default template Chutzpah uses for the HTML test harness. This is an advanced feature which should only be used as a last resort.",
      "type": "string"
    },
    "MochaInterface": {
      "description": "The name of the Mocha interface to use. Overrides the default detection mechanism.",
      "type": "string",
      "enum": ["bdd", "tdd", "qunit"]
    },
    "AMDBaseUrl": {
      "description": "Set the baseurl for Chutzpah to use when generating the test harness. Defaults to the test harness directory if not set.",
      "type": "string"
    },
    "AMDAppDirectory": {
      "description": "Sets the root directory for your AMD paths. This is only needed if your baseUrl is a different location than your source directory. This is common if you are compiling from another language to JavaScript and copying those compiled files to a different folder. For example if you have all your .ts files in /src and you compile them to a /out directory then your AMDBaseUrl is /out and AMDAppDirectory is /src. Defaults to the test harness directory if not set.",
      "type": "string"
    },
    "UserAgent": {
      "description": "The user agent to use when making web requests",
      "type": "string"
    },
    "TestPattern": {
      "description": "When Chutzpah reports test results it also tells you what line they are on. The way this is accomplished is by having a regex for each testing framework which describes where to find the names of your tests.",
      "type": "string",
      "format": "regex"
    },
    "EnableTestFileBatching": {
      "description": "Determines if batch all test files for this chutzpah.json file should be batched into one test harness. This will often make your test run much faster.",
      "type": "boolean"
    },
    "InheritFromParent": {
      "description": "Determines if this settings file should inherit and merge with the settings of its parent settings file. The parent is found by recursively walking up the tree.",
      "type": "boolean"
    },
    "IgnoreResourceLoadingErrors": {
      "description": "Suppress errors that are reported when a script request to load a url (e.g. xhr/script/image) fails.",
      "type": "boolean"
    },
    "EnableTracing": {
      "description": "Logs tracing information to a log file.",
      "type": "boolean"
    },
    "TraceFilePath": {
      "description": "The path to write the trace file to. Defaults tp %temp%/chutzpah.log.",
      "type": "string"
    },
    "Parallelism": {
      "description": "Max degree of parallelism for running tests. Defaults to number of CPUs",
      "type": "number"
    },
    "BrowserArguments": {
      "description": "The dictionary of browser name (keys) to corresponding browser arguments (values), i.e.; { 'chrome': '--allow-file-access-from-files' }.",
      "type": "object"
    }
  },
  "title": "JSON schema for Chutzpah test runner settings files",
  "type": "object"
}

{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "title": "shopware-cli",
    "description": "shopware cli project configuration definition file",
    "$ref": "#/definitions/Config",
    "definitions": {
        "Config": {
            "type": "object",
            "title": ".shopware-project.yml",
            "additionalProperties": false,
            "properties": {
                "url": {
                    "type": "string",
                    "description": "URL to Shopware instance"
                },
                "admin_api": {
                    "$ref": "#/definitions/AdminApi"
                },
                "dump": {
                    "$ref": "#/definitions/Dump"
                },
                "sync": {
                    "$ref": "#/definitions/Sync"
                },
                "build": {
                    "$ref": "#/definitions/Build"
                }
            }
        },
        "Build": {
            "type": "object",
            "title": "Project Build Settings",
            "additionalProperties": false,
            "properties": {
                "disable_asset_copy": {
                    "type": "boolean",
                    "description": "When enabled, the assets will not be copied to the public folder",
                    "default": false
                },
                "remove_extension_assets": {
                    "type": "boolean",
                    "description": "When enabled, the assets of extensions will be removed from the extension public folder. (Requires Shopware 6.5.2.0)",
                    "default": false
                },
                "cleanup_paths": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Paths to delete for the final build"
                }
            }
        },
        "AdminApi": {
            "type": "object",
            "title": "Admin API credentials",
            "additionalProperties": false,
            "properties": {
                "client_id": {
                    "type": "string",
                    "description": "Client ID of integration"
                },
                "client_secret": {
                    "type": "string",
                    "description": "Client Secret of integration"
                },
                "username": {
                    "type": "string",
                    "description": "Username of admin user"
                },
                "password": {
                    "type": "string",
                    "description": "Password of admin user"
                },
                "disable_ssl_check": {
                    "type": "boolean",
                    "description": "Disable SSL check for API requests",
                    "default": false
                }
            }
        },
        "Dump": {
            "type": "object",
            "title": "MySQL dump configuration",
            "additionalProperties": false,
            "properties": {
                "rewrite": {
                    "type": "object"
                },
                "nodata": {
                    "type": "array",
                    "items": {"type": "string"}
                },
                "ignore": {
                    "type": "array",
                    "items": {"type": "string"}
                },
                "where": {
                    "type": "object"
                }
            }
        },
        "Sync": {
            "type": "object",
            "title": "Sync Settings",
            "additionalProperties": false,
            "properties": {
                "config": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/SyncConfigItem"}
                },
                "theme": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/ThemeConfigItem"}
                },
                "mail_template": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/MailTemplateItem"}
                },
                "entity": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/EntitySyncItem"}
                }
            }
        },
        "SyncConfigItem": {
            "type": "object",
            "title": "System Config Sync",
            "additionalProperties": false,
            "properties": {
                "sales_channel": {
                    "title": "Sales Channel to apply",
                    "type": "string"
                },
                "settings": {
                    "type": "object"
                }
            },
            "required": ["settings"]
        },
        "ThemeConfigItem": {
            "type": "object",
            "title": "Theme Config Sync",
            "additionalProperties": false,
            "properties": {
                "name": {
                    "type": "string"
                },
                "settings": {
                    "type": "object"
                }
            }
        },
        "MailTemplateItem": {
            "type": "object",
            "title": "Mail Template Sync",
            "additionalProperties": false,
            "properties": {
                "id": {
                    "type": "string"
                },
                "translations": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/MailTemplateItemTranslation"}
                }
            }
        },
        "MailTemplateItemTranslation": {
            "type": "object",
            "title": "Mail Template Single Translation",
            "additionalProperties": false,
            "properties": {
                "language": {
                    "type": "string"
                },
                "sender_name": {
                    "type": "string"
                },
                "subject": {
                    "type": "string"
                },
                "html": {
                    "type": "string"
                },
                "plain": {
                    "type": "string"
                },
                "custom_fields": {
                    "type": ["object", "null"]
                }
            }
        },
        "EntitySyncItem": {
            "type": "object",
            "title": "Entity Sync",
            "additionalProperties": false,
            "properties": {
                "entity": {
                    "type": "string"
                },
                "exists": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/EntitySyncFilter"}
                },
                "payload": {
                    "type": "object",
                    "description": "API payload"
                }
            },
            "required": ["entity", "payload"]
        },
        "EntitySyncFilter": {
            "type": "object",
            "title": "Entity Sync Filter",
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "enum": ["equals", "multi", "contains", "prefix", "suffix", "not", "range", "until", "equalsAll" ,"equalsAny"],
                    "description": "filter type"
                },
                "field": {
                    "type": "string",
                    "description": "field"
                },
                "value": {
                    "type": ["string", "integer", "array", "boolean", "null"],
                    "description": "value"
                },
                "operator": {
                    "type": "string",
                    "enum": ["AND", "OR", "XOR"]
                },
                "queries": {
                    "type": "array",
                    "items": {"$ref": "#/definitions/EntitySyncFilterInner"}
                }
            },
            "required": ["type", "field"],
            "allOf": [
                {
                    "if": {
                        "properties": {
                            "type": {
                                "const": "multi"
                            }
                        }
                    },
                    "then": {
                        "required": ["type", "queries"]
                    }
                }
            ]
        },
        "EntitySyncFilterInner": {
            "type": "object",
            "title": "Entity Sync Filter",
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "enum": ["equals", "multi", "contains", "prefix", "suffix", "not", "range", "until", "equalsAll" ,"equalsAny"],
                    "description": "filter type"
                },
                "field": {
                    "type": "string",
                    "description": "field"
                },
                "value": {
                    "type": ["string", "integer", "array", "boolean", "null"],
                    "description": "value"
                },
                "operator": {
                    "type": "string",
                    "enum": ["AND", "OR", "XOR"]
                }
            },
            "required": ["type", "field"],
            "allOf": [
                {
                    "if": {
                        "properties": {
                            "type": {
                                "const": "multi"
                            }
                        }
                    },
                    "then": {
                        "required": ["type", "queries"]
                    }
                }
            ]
        }
    }
}

{
  "$id": "https://json.schemastore.org/rustfmt.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "description": "https://rust-lang.github.io/rustfmt",
  "properties": {
    "array_width": {
      "type": "integer",
      "description": "Maximum width of an array literal before falling back to vertical formatting.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#array_width)",
      "default": 60
    },
    "attr_fn_like_width": {
      "type": "integer",
      "description": "Maximum width of the args of a function-like attributes before falling back to vertical formatting.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#attr_fn_like_width)",
      "default": 70
    },
    "binop_separator": {
      "type": "string",
      "description": "Where to put a binary operator when a binary expression goes multiline\n\n[Documentation](https://rust-lang.github.io/rustfmt/#binop_separator)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Front",
      "enum": ["Front", "Back"]
    },
    "blank_lines_lower_bound": {
      "type": "integer",
      "description": "Minimum number of blank lines which must be put between items\n\n[Documentation](https://rust-lang.github.io/rustfmt/#blank_lines_lower_bound)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": 0
    },
    "blank_lines_upper_bound": {
      "type": "integer",
      "description": "Maximum number of blank lines which can be put between items\n\n[Documentation](https://rust-lang.github.io/rustfmt/#blank_lines_upper_bound)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": 1
    },
    "brace_style": {
      "type": "string",
      "description": "Brace style for items\n\n[Documentation](https://rust-lang.github.io/rustfmt/#brace_style)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "SameLineWhere",
      "enum": ["AlwaysNextLine", "PreferSameLine", "SameLineWhere"]
    },
    "chain_width": {
      "type": "integer",
      "description": "Maximum length of a chain to fit on a single line.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#chain_width)",
      "default": 60
    },
    "color": {
      "type": "string",
      "description": "What Color option to use when none is supplied: Always, Never, Auto\n\n[Documentation](https://rust-lang.github.io/rustfmt/#color)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Auto",
      "enum": ["Always", "Never", "Auto"]
    },
    "combine_control_expr": {
      "type": "boolean",
      "description": "Combine control expressions with function calls\n\n[Documentation](https://rust-lang.github.io/rustfmt/#combine_control_expr)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "comment_width": {
      "type": "integer",
      "description": "Maximum length of comments. No effect unless wrap_comments = true\n\n[Documentation](https://rust-lang.github.io/rustfmt/#comment_width)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": 80
    },
    "condense_wildcard_suffixes": {
      "type": "boolean",
      "description": "Replace strings of _ wildcards by a single .. in tuple patterns\n\n[Documentation](https://rust-lang.github.io/rustfmt/#condense_wildcard_suffixes)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "control_brace_style": {
      "type": "string",
      "description": "Brace style for control flow constructs\n\n[Documentation](https://rust-lang.github.io/rustfmt/#control_brace_style)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "AlwaysSameLine",
      "enum": ["AlwaysSameLine", "ClosingNextLine", "AlwaysNextLine"]
    },
    "disable_all_formatting": {
      "type": "boolean",
      "description": "Don't reformat anything\n\n[Documentation](https://rust-lang.github.io/rustfmt/#disable_all_formatting)",
      "default": false,
      "enum": [true, false]
    },
    "edition": {
      "type": "string",
      "description": "The edition of the parser (RFC 2052)\n\n[Documentation](https://rust-lang.github.io/rustfmt/#edition)",
      "default": "2015",
      "enum": ["2015", "2018", "2021"]
    },
    "emit_mode": {
      "type": "string",
      "description": "What emit Mode to use when none is supplied\n\n[Documentation](https://rust-lang.github.io/rustfmt/#emit_mode)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Files",
      "enum": [
        "Files",
        "Stdout",
        "Coverage",
        "Checkstyle",
        "Json",
        "ModifiedLines",
        "Diff"
      ]
    },
    "empty_item_single_line": {
      "type": "boolean",
      "description": "Put empty-body functions and impls on a single line\n\n[Documentation](https://rust-lang.github.io/rustfmt/#empty_item_single_line)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "enum_discrim_align_threshold": {
      "type": "integer",
      "description": "Align enum variants discrims, if their diffs fit within threshold\n\n[Documentation](https://rust-lang.github.io/rustfmt/#enum_discrim_align_threshold)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": 0
    },
    "error_on_line_overflow": {
      "type": "boolean",
      "description": "Error if unable to get all lines within max_width\n\n[Documentation](https://rust-lang.github.io/rustfmt/#error_on_line_overflow)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "error_on_unformatted": {
      "type": "boolean",
      "description": "Error if unable to get comments or string literals within max_width, or they are left with trailing whitespaces\n\n[Documentation](https://rust-lang.github.io/rustfmt/#error_on_unformatted)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "fn_args_layout": {
      "type": "string",
      "description": "Control the layout of arguments in a function\n\n[Documentation](https://rust-lang.github.io/rustfmt/#fn_args_layout)",
      "default": "Tall",
      "enum": ["Compressed", "Tall", "Vertical"]
    },
    "fn_call_width": {
      "type": "integer",
      "description": "Maximum width of the args of a function call before falling back to vertical formatting.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#fn_call_width)",
      "default": 60
    },
    "fn_single_line": {
      "type": "boolean",
      "description": "Put single-expression functions on a single line\n\n[Documentation](https://rust-lang.github.io/rustfmt/#fn_single_line)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "force_explicit_abi": {
      "type": "boolean",
      "description": "Always print the abi for extern items\n\n[Documentation](https://rust-lang.github.io/rustfmt/#force_explicit_abi)",
      "default": true,
      "enum": [true, false]
    },
    "force_multiline_blocks": {
      "type": "boolean",
      "description": "Force multiline closure bodies and match arms to be wrapped in a block\n\n[Documentation](https://rust-lang.github.io/rustfmt/#force_multiline_blocks)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "format_code_in_doc_comments": {
      "type": "boolean",
      "description": "Format the code snippet in doc comments.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#format_code_in_doc_comments)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "format_generated_files": {
      "type": "boolean",
      "description": "Format generated files\n\n[Documentation](https://rust-lang.github.io/rustfmt/#format_generated_files)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "format_macro_bodies": {
      "type": "boolean",
      "description": "Format the bodies of macros\n\n[Documentation](https://rust-lang.github.io/rustfmt/#format_macro_bodies)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "format_macro_matchers": {
      "type": "boolean",
      "description": "Format the metavariable matching patterns in macros\n\n[Documentation](https://rust-lang.github.io/rustfmt/#format_macro_matchers)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "format_strings": {
      "type": "boolean",
      "description": "Format string literals where necessary\n\n[Documentation](https://rust-lang.github.io/rustfmt/#format_strings)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "group_imports": {
      "type": "string",
      "description": "Controls the strategy for how imports are grouped together\n\n[Documentation](https://rust-lang.github.io/rustfmt/#group_imports)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Preserve",
      "enum": ["Preserve", "StdExternalCrate", "One"]
    },
    "hard_tabs": {
      "type": "boolean",
      "description": "Use tab characters for indentation, spaces for alignment\n\n[Documentation](https://rust-lang.github.io/rustfmt/#hard_tabs)",
      "default": false,
      "enum": [true, false]
    },
    "hex_literal_case": {
      "type": "string",
      "description": "Format hexadecimal integer literals\n\n[Documentation](https://rust-lang.github.io/rustfmt/#hex_literal_case)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Preserve",
      "enum": ["Preserve", "Upper", "Lower"]
    },
    "hide_parse_errors": {
      "type": "boolean",
      "description": "Hide errors from the parser\n\n[Documentation](https://rust-lang.github.io/rustfmt/#hide_parse_errors)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "ignore": {
      "type": "array",
      "description": "Skip formatting the specified files and directories\n\n[Documentation](https://rust-lang.github.io/rustfmt/#ignore)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": []
    },
    "imports_granularity": {
      "type": "string",
      "description": "Merge or split imports to the provided granularity\n\n[Documentation](https://rust-lang.github.io/rustfmt/#imports_granularity)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Preserve",
      "enum": ["Preserve", "Crate", "Module", "Item", "One"]
    },
    "imports_indent": {
      "type": "string",
      "description": "Indent of imports\n\n[Documentation](https://rust-lang.github.io/rustfmt/#imports_indent)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Block",
      "enum": ["Visual", "Block"]
    },
    "imports_layout": {
      "type": "string",
      "description": "Item layout inside a import block\n\n[Documentation](https://rust-lang.github.io/rustfmt/#imports_layout)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Mixed",
      "enum": [
        "Vertical",
        "Horizontal",
        "HorizontalVertical",
        "LimitedHorizontalVertical",
        "Mixed"
      ]
    },
    "indent_style": {
      "type": "string",
      "description": "How do we indent expressions or items\n\n[Documentation](https://rust-lang.github.io/rustfmt/#indent_style)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Block",
      "enum": ["Visual", "Block"]
    },
    "inline_attribute_width": {
      "type": "integer",
      "description": "Write an item and its attribute on the same line if their combined width is below a threshold\n\n[Documentation](https://rust-lang.github.io/rustfmt/#inline_attribute_width)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": 0
    },
    "license_template_path": {
      "type": "string",
      "description": "Beginning of file must match license template\n\n[Documentation](https://rust-lang.github.io/rustfmt/#license_template_path)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "\"\""
    },
    "make_backup": {
      "type": "boolean",
      "description": "Backup changed files\n\n[Documentation](https://rust-lang.github.io/rustfmt/#make_backup)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "match_arm_blocks": {
      "type": "boolean",
      "description": "Wrap the body of arms in blocks when it does not fit on the same line with the pattern of arms\n\n[Documentation](https://rust-lang.github.io/rustfmt/#match_arm_blocks)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "match_arm_leading_pipes": {
      "type": "string",
      "description": "Determines whether leading pipes are emitted on match arms\n\n[Documentation](https://rust-lang.github.io/rustfmt/#match_arm_leading_pipes)",
      "default": "Never",
      "enum": ["Always", "Never", "Preserve"]
    },
    "match_block_trailing_comma": {
      "type": "boolean",
      "description": "Put a trailing comma after a block based match arm (non-block arms are not affected)\n\n[Documentation](https://rust-lang.github.io/rustfmt/#match_block_trailing_comma)",
      "default": false,
      "enum": [true, false]
    },
    "max_width": {
      "type": "integer",
      "description": "Maximum width of each line\n\n[Documentation](https://rust-lang.github.io/rustfmt/#max_width)",
      "default": 100
    },
    "merge_derives": {
      "type": "boolean",
      "description": "Merge multiple `#[derive(...)]` into a single one\n\n[Documentation](https://rust-lang.github.io/rustfmt/#merge_derives)",
      "default": true,
      "enum": [true, false]
    },
    "newline_style": {
      "type": "string",
      "description": "Unix or Windows line endings\n\n[Documentation](https://rust-lang.github.io/rustfmt/#newline_style)",
      "default": "Auto",
      "enum": ["Auto", "Windows", "Unix", "Native"]
    },
    "normalize_comments": {
      "type": "boolean",
      "description": "Convert /* */ comments to // comments where possible\n\n[Documentation](https://rust-lang.github.io/rustfmt/#normalize_comments)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "normalize_doc_attributes": {
      "type": "boolean",
      "description": "Normalize doc attributes as doc comments\n\n[Documentation](https://rust-lang.github.io/rustfmt/#normalize_doc_attributes)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "overflow_delimited_expr": {
      "type": "boolean",
      "description": "Allow trailing bracket/brace delimited expressions to overflow\n\n[Documentation](https://rust-lang.github.io/rustfmt/#overflow_delimited_expr)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "print_misformatted_file_names": {
      "type": "boolean",
      "description": "Prints the names of mismatched files that were formatted. Prints the names of files that would be formated when used with `--check` mode.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#print_misformatted_file_names)",
      "default": false,
      "enum": [true, false]
    },
    "remove_nested_parens": {
      "type": "boolean",
      "description": "Remove nested parens\n\n[Documentation](https://rust-lang.github.io/rustfmt/#remove_nested_parens)",
      "default": true,
      "enum": [true, false]
    },
    "reorder_impl_items": {
      "type": "boolean",
      "description": "Reorder impl items\n\n[Documentation](https://rust-lang.github.io/rustfmt/#reorder_impl_items)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "reorder_imports": {
      "type": "boolean",
      "description": "Reorder import and extern crate statements alphabetically\n\n[Documentation](https://rust-lang.github.io/rustfmt/#reorder_imports)",
      "default": true,
      "enum": [true, false]
    },
    "reorder_modules": {
      "type": "boolean",
      "description": "Reorder module statements alphabetically in group\n\n[Documentation](https://rust-lang.github.io/rustfmt/#reorder_modules)",
      "default": true,
      "enum": [true, false]
    },
    "report_fixme": {
      "type": "string",
      "description": "Report all, none or unnumbered occurrences of FIXME in source file comments\n\n[Documentation](https://rust-lang.github.io/rustfmt/#report_fixme)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Never",
      "enum": ["Always", "Unnumbered", "Never"]
    },
    "report_todo": {
      "type": "string",
      "description": "Report all, none or unnumbered occurrences of TODO in source file comments\n\n[Documentation](https://rust-lang.github.io/rustfmt/#report_todo)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Never",
      "enum": ["Always", "Unnumbered", "Never"]
    },
    "required_version": {
      "type": "string",
      "description": "Require a specific version of rustfmt\n\n[Documentation](https://rust-lang.github.io/rustfmt/#required_version)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "1.4.38"
    },
    "single_line_if_else_max_width": {
      "type": "integer",
      "description": "Maximum line length for single line if-else expressions. A value of zero means always break if-else expressions.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#single_line_if_else_max_width)",
      "default": 50
    },
    "skip_children": {
      "type": "boolean",
      "description": "Don't reformat out of line modules\n\n[Documentation](https://rust-lang.github.io/rustfmt/#skip_children)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "space_after_colon": {
      "type": "boolean",
      "description": "Leave a space after the colon\n\n[Documentation](https://rust-lang.github.io/rustfmt/#space_after_colon)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "space_before_colon": {
      "type": "boolean",
      "description": "Leave a space before the colon\n\n[Documentation](https://rust-lang.github.io/rustfmt/#space_before_colon)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "spaces_around_ranges": {
      "type": "boolean",
      "description": "Put spaces around the  .. and ..= range operators\n\n[Documentation](https://rust-lang.github.io/rustfmt/#spaces_around_ranges)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "struct_field_align_threshold": {
      "type": "integer",
      "description": "Align struct fields if their diffs fits within threshold\n\n[Documentation](https://rust-lang.github.io/rustfmt/#struct_field_align_threshold)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": 0
    },
    "struct_lit_single_line": {
      "type": "boolean",
      "description": "Put small struct literals on a single line\n\n[Documentation](https://rust-lang.github.io/rustfmt/#struct_lit_single_line)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "struct_lit_width": {
      "type": "integer",
      "description": "Maximum width in the body of a struct lit before falling back to vertical formatting.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#struct_lit_width)",
      "default": 18
    },
    "struct_variant_width": {
      "type": "integer",
      "description": "Maximum width in the body of a struct variant before falling back to vertical formatting.\n\n[Documentation](https://rust-lang.github.io/rustfmt/#struct_variant_width)",
      "default": 35
    },
    "tab_spaces": {
      "type": "integer",
      "description": "Number of spaces per tab\n\n[Documentation](https://rust-lang.github.io/rustfmt/#tab_spaces)",
      "default": 4
    },
    "trailing_comma": {
      "type": "string",
      "description": "How to handle trailing commas for lists\n\n[Documentation](https://rust-lang.github.io/rustfmt/#trailing_comma)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Vertical",
      "enum": ["Always", "Never", "Vertical"]
    },
    "trailing_semicolon": {
      "type": "boolean",
      "description": "Add trailing semicolon after break, continue and return\n\n[Documentation](https://rust-lang.github.io/rustfmt/#trailing_semicolon)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": true,
      "enum": [true, false]
    },
    "type_punctuation_density": {
      "type": "string",
      "description": "Determines if '+' or '=' are wrapped in spaces in the punctuation of types\n\n[Documentation](https://rust-lang.github.io/rustfmt/#type_punctuation_density)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "Wide",
      "enum": ["Compressed", "Wide"]
    },
    "unstable_features": {
      "type": "boolean",
      "description": "Enables unstable features. Only available on nightly channel\n\n[Documentation](https://rust-lang.github.io/rustfmt/#unstable_features)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "use_field_init_shorthand": {
      "type": "boolean",
      "description": "Use field initialization shorthand if possible\n\n[Documentation](https://rust-lang.github.io/rustfmt/#use_field_init_shorthand)",
      "default": false,
      "enum": [true, false]
    },
    "use_small_heuristics": {
      "type": "string",
      "description": "Whether to use different formatting for items and expressions if they satisfy a heuristic notion of 'small'\n\n[Documentation](https://rust-lang.github.io/rustfmt/#use_small_heuristics)",
      "default": "Default",
      "enum": ["Off", "Max", "Default"]
    },
    "use_try_shorthand": {
      "type": "boolean",
      "description": "Replace uses of the try! macro by the ? shorthand\n\n[Documentation](https://rust-lang.github.io/rustfmt/#use_try_shorthand)",
      "default": false,
      "enum": [true, false]
    },
    "version": {
      "type": "string",
      "description": "Version of formatting rules\n\n[Documentation](https://rust-lang.github.io/rustfmt/#version)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": "One",
      "enum": ["One", "Two"]
    },
    "where_single_line": {
      "type": "boolean",
      "description": "Force where-clauses to be on a single line\n\n[Documentation](https://rust-lang.github.io/rustfmt/#where_single_line)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    },
    "wrap_comments": {
      "type": "boolean",
      "description": "Break comments to fit on the line\n\n[Documentation](https://rust-lang.github.io/rustfmt/#wrap_comments)\n\n### Unstable\nThis option requires Nightly Rust.",
      "default": false,
      "enum": [true, false]
    }
  },
  "title": "rustfmt schema",
  "type": "object",
  "x-taplo-info": {
    "authors": ["Aloso (https://github.com/Aloso)"],
    "patterns": ["^(.*(/|\\\\)\\.?rustfmt\\.toml|rustfmt\\.toml)$"]
  }
