      "properties": {
        "name": {
          "type": "string",
          "description": "The name of the profile.",
          "examples": ["dbb-build"]
        },
        "type": {
          "type": "string",
          "enum": ["dbb", "rseapi", "debug"],
          "description": "The type of the profile.",
          "default": "dbb",
          "examples": ["dbb", "rseapi"]
        },
        "settings": {
          "description": "Settings objects specific to the type specified for the profile.",
          "type": "object"
        }
      },
      "anyOf": [
        {
          "required": ["name", "type", "settings"],
          "additionalProperties": false,
          "properties": {
            "name": { "type": "string" },
            "type": { "const": "dbb", "type": "string" },
            "settings": {
              "$ref": "#/definitions/dbbSettingsItem"
            }
          }
        },
        {
          "required": ["name", "type", "settings"],
          "additionalProperties": false,
          "properties": {
            "name": { "type": "string" },
            "type": { "const": "rseapi", "type": "string" },
            "settings": {
              "$ref": "#/definitions/rseapiSettingsItem"
            }
          }
        }
      ]
    },
    "dbbSettingsItem": {
      "type": "object",
      "additionalProperties": false,
      "required": ["application", "command"],
      "description": "DBB build script properties for running User Build on remote host.",
      "properties": {
        "application": {
          "type": "string",
          "description": "Defines the name of the application to build. Will be used to create a folder on USS to upload all files to."
        },
        "command": {
          "type": "string",
          "description": "Command that the build script is executed with such as the path to groovyz and it's parameters."
        },
        "buildScriptPath": {
          "type": "string",
          "description": "The full path of build script on the remote host that should be used with the command."
        },
        "buildScriptArgs": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "A list of strings that are the parameters for the build script. Check the documentation for built-in variables, such as the name of the program to build, that can be used here."
        },
        "additionalDependencies": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Lists of GLOB patterns that define the files that should be uploaded to USS for a build. Relative path names are interpreted relative to the location of the ZAPP file that is being used for the build, which is a ZAPP file in the same workspace as the program to be build."
        },
        "logFilePatterns": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Lists of GLOB patterns that define the files that should be downloaded from USS after the build. Relative path names are interpreted relative to the DBB log directory user setting. If not provided then all files of the user setting location will be downloaded."
        }
      }
    },
    "rseapiSettingsItem": {
      "type": "object",
      "additionalProperties": false,
      "description": "RSE API client settings for interactions with a z/OS remote host running an RSE API server.",
      "required": ["mappings", "default.encoding"],
      "properties": {
        "mappings": {
          "type": "array",
          "description": "A list of mapping objects that map local file extensions to transfer modes and encodings to MVS datasets that can be specified using wildcards.",
          "items": { "$ref": "#/definitions/rseapiSettingsItemMapping" }
        },
        "default.encoding": {
          "type": "string",
          "description": "The encoding to be used when no mapping can be found. If not provided then either the user or server default will be used."
        }
      }
    },
    "rseapiSettingsItemMapping": {
      "type": "object",
      "additionalProperties": false,
      "description": "One mapping that contains at least transfer and resource values.",
      "properties": {
        "extension": {
          "type": "string",
          "description": "A local file extension such as cbl or pl1."
        },
        "transfer": {
          "type": "string",
          "enum": ["text", "binary"],
          "description": "The transfer mode to be used. Can be 'text' or 'binary'."
        },
        "resource": {
          "type": "string",
          "description": "The data set name to be mapped to. Can use a wildcard such as '**CPY'."
        },
        "encoding": {
          "type": "string",
          "description": "The encoding to be used for text transfer. See the RSE API documentation for the values allowed."
        },
        "memberMappings": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "description": "One member mapping that contains at least transfer and resource values.",
            "properties": {
              "extension": {
                "type": "string",
                "description": "A local file extension such as cbl or pl1."
              },
              "transfer": {
                "type": "string",
                "enum": ["text", "binary"],
                "description": "The transfer mode to be used. Can be 'text' or 'binary'."
              },
              "encoding": {
                "type": "string",
                "description": "The encoding to be used for text transfer. See the RSE API documentation for the values allowed."
              },
              "resource": {
                "type": "string",
                "description": "The data set member name to be mapped to. Can use a wildcard such as '**CPY'."
              }
            }
          },
          "description": "A nested mappings array with resource mappings to members of the data sets that were mapped by the parent mapping."
        }
      }
    }
  },
  "anyOf": [
    {
      "$ref": "#/definitions/coreProperties"
    }
  ]
}

{
  "$id": "https://json.schemastore.org/pubspec",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+(?:[+-]\\S+)?$"
    },
    "versionConstraint": {
      "description": "Version range of the package or SDK to use",
      "oneOf": [
        {
          "type": "string",
          "description": "Allows any version of the package. This is not recommended for performance reasons",
          "enum": ["any", ""]
        },
        {
          "$ref": "#/definitions/version"
        },
        {
          "type": "string",
          "examples": [">1.0.0 <2.3.0-beta", ">=1.0.0-pre.1 <=3.0.0"],
          "pattern": "^(?:(?:>=|>|<=|<)\\d+\\.\\d+\\.\\d+(?:[+-]\\S+)?\\s*)+$"
        },
        {
          "type": "string",
          "examples": ["^1.0.0"],
          "pattern": "^\\^\\d+\\.\\d+\\.\\d+(?:[+-]\\S+)?$"
        }
      ]
    },
    "dependency": {
      "oneOf": [
        {
          "$ref": "#/definitions/versionConstraint",
          "$comment": "Syntax in yaml: `foo: ^1.2.3`"
        },
        {
          "description": "Default dependency, matches any version of the package",
          "type": "null",
          "$comment": "Syntax in yaml: `foo:` or `foo: null`"
        },
        {
          "title": "SDK dependency",
          "type": "object",
          "properties": {
            "sdk": {
              "description": "The SDK which contains this package",
              "type": "string"
            },
            "version": {
              "$ref": "#/definitions/versionConstraint"
            }
          },
          "required": ["sdk"],
          "additionalProperties": false
        },
        {
          "title": "Hosted dependency",
          "type": "object",
          "properties": {
            "hosted": {
              "oneOf": [
                {
                  "type": "string",
                  "description": "URL of the package server hosting this package",
                  "format": "uri"
                },
                {
                  "type": "object",
                  "properties": {
                    "name": {
                      "type": "string"
                    },
                    "url": {
                      "description": "The package server hosting this package",
                      "type": "string",
                      "format": "uri"
                    }
                  },
                  "required": ["url"]
                }
              ]
            },
            "version": {
              "$ref": "#/definitions/versionConstraint"
            }
          },
          "required": ["hosted"],
          "additionalProperties": false
        },
        {
          "description": "Git dependency",
          "type": "object",
          "properties": {
            "git": {
              "$comment": "Can either be a string (uri) or an object with ref etc.",
              "oneOf": [
                {
                  "description": "URI of the repository hosting this package",
                  "type": "string"
                },
                {
                  "type": "object",
                  "properties": {
                    "url": {
                      "type": "string",
                      "description": "URI of the repository hosting this package"
                    },
                    "path": {
                      "type": "string",
                      "description": "Path of this package relative to the Git repo's root"
                    },
                    "ref": {
                      "type": "string",
                      "description": "The branch, tag, or anything else Git allows to identify a commit."
                    }
                  }
                }
              ]
            }
          },
          "required": ["git"],
          "additionalProperties": false
        },
        {
          "description": "Path dependency",
          "type": "object",
          "properties": {
            "path": {
              "type": "string"
            }
          },
          "additionalProperties": false
        }
      ]
    },
    "dependencies": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/dependency"
      }
    }
  },
  "description": "Dart Pubspec file",
  "properties": {
    "name": {
      "description": "The name of this package. The name is how other packages refer to yours, should you publish it.",
      "type": "string"
    },
    "version": {
      "$ref": "#/definitions/version"
    },
    "description": {
      "type": "string"
    },
    "authors": {
      "type": "array",
      "deprecated": true,
      "items": {
        "type": "string"
      }
    },
    "homepage": {
      "type": "string",
      "format": "uri"
    },
    "repository": {
      "type": "string",
      "format": "uri"
    },
    "issue_tracker": {
      "type": "string",
      "format": "uri"
    },
    "documentation": {
      "type": "string",
      "format": "uri"
    },
    "executables": {
      "type": "object"
    },
    "publish_to": {
      "type": "string"
    },
    "environment": {
      "type": "object",
      "examples": [
        {
          "sdk": ">=1.19.0 <3.0.0",
          "flutter": "^0.1.2"
        }
      ],
      "additionalProperties": {
        "$ref": "#/definitions/versionConstraint"
      }
    },
    "dependencies": {
      "$ref": "#/definitions/dependencies"
    },
    "dev_dependencies": {
      "$ref": "#/definitions/dependencies"
    },
    "dependency_overrides": {
      "$ref": "#/definitions/dependencies"
    }
  },
  "required": ["name"],
  "title": "Pubspec",
  "type": "object"
}

{
  "$defs": {
    "file": {
      "oneOf": [
        {
          "description": "This object or string represents the file format",
          "type": "string"
