{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "https://raw.githubusercontent.com/ansible/ansible-rulebook/main/ansible_rulebook/schema/ruleset_schema.json",
    "type": "array",
    "items": {
        "$ref": "#/$defs/ruleset"
    },
    "minItems": 1,
    "examples": [
        "rulebooks/*.yml",
        "rulebooks/*.yaml"
    ],
    "$defs": {
        "ruleset": {
            "type": "object",
            "properties": {
                "default_events_ttl": {
                    "type": "string",
                    "pattern": "^\\d+\\s(seconds?|minutes?|hours?|days?)$"
                },
                "hosts": {
                    "type": "string"
                },
                "gather_facts": {
                    "type": "boolean",
                    "default": false
                },
                "match_multiple_rules": {
                    "type": "boolean",
                    "default": false
                },
                "name": {
                    "type": "string"
                },
                "execution_strategy": {
                    "type": "string",
                    "enum": [
                        "parallel",
                        "sequential"
                    ],
                    "default": "sequential"
                },
                "sources": {
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/source"
                    }
                },
                "rules": {
                    "type": "array",
                    "items": {
                        "$ref": "#/$defs/rule"
                    }
                }
            },
            "required": [
                "hosts",
                "sources",
                "rules"
            ],
            "additionalProperties": false
        },
        "source": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string"
                },
                "filters": {
                    "type": "array",
                    "items": {
                        "type": "object"
                    }
                }
            },
            "additionalProperties": {
                "oneOf": [
                    {
                        "type": "object"
                    },
                    {
                        "type": "null"
                    }
                ]
            }
        },
        "throttle": {
            "type": "object",
            "oneOf": [
                {
                    "required": [
                        "once_within",
                        "group_by_attributes"
                    ]
                },
                {
                    "required": [
                        "once_after",
                        "group_by_attributes"
                    ]
                }
            ],
            "properties": {
                "once_within": {
                    "type": "string",
                    "pattern": "^\\d+\\s(milliseconds?|seconds?|minutes?|hours?|days?)$"
                },
                "once_after": {
                    "type": "string",
                    "pattern": "^\\d+\\s(milliseconds?|seconds?|minutes?|hours?|days?)$"
                },
                "group_by_attributes": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            },
            "additionalProperties": false
        },
        "rule": {
            "type": "object",
            "oneOf": [
                {
                    "required": [
                        "name",
                        "condition",
                        "actions"
                    ]
                },
                {
                    "required": [
                        "name",
                        "condition",
                        "action"
                    ]
                }
            ],
            "properties": {
                "name": {
                    "type": "string",
                    "minLength": 1,
                    "pattern": "\\S"
                },
                "enabled": {
                    "type": "boolean"
                },
                "throttle": {
                    "$ref": "#/$defs/throttle"
                },
                "condition": {
                    "anyOf": [
                        {
                            "type": "string"
                        },
                        {
                            "$ref": "#/$defs/all-condition"
                        },
                        {
                            "$ref": "#/$defs/any-condition"
                        },
                        {
                            "$ref": "#/$defs/not-all-condition"
                        }
                    ]
                },
                "actions": {
                    "type": "array",
                    "items": {
                        "oneOf": [
                            {
                                "$ref": "#/$defs/run-playbook-action"
                            },
                            {
                                "$ref": "#/$defs/run-module-action"
                            },
                            {
                                "$ref": "#/$defs/run-job-template-action"
                            },
                            {
                                "$ref": "#/$defs/run-workflow-template-action"
                            },
                            {
                                "$ref": "#/$defs/post-event-action"
                            },
                            {
                                "$ref": "#/$defs/set-fact-action"
                            },
                            {
                                "$ref": "#/$defs/retract-fact-action"
                            },
                            {
                                "$ref": "#/$defs/print-event-action"
                            },
                            {
                                "$ref": "#/$defs/debug-action"
                            },
                            {
                                "$ref": "#/$defs/none-action"
                            },
                            {
                                "$ref": "#/$defs/shutdown-action"
                            }
                        ]
                    }
                },
                "action": {
                    "oneOf": [
                        {
                            "$ref": "#/$defs/run-playbook-action"
                        },
                        {
                            "$ref": "#/$defs/run-module-action"
                        },
                        {
                            "$ref": "#/$defs/run-job-template-action"
                        },
                        {
                            "$ref": "#/$defs/run-workflow-template-action"
                        },
                        {
                            "$ref": "#/$defs/post-event-action"
                        },
                        {
                            "$ref": "#/$defs/set-fact-action"
                        },
                        {
                            "$ref": "#/$defs/retract-fact-action"
                        },
                        {
                            "$ref": "#/$defs/print-event-action"
                        },
                        {
                            "$ref": "#/$defs/debug-action"
                        },
                        {
                            "$ref": "#/$defs/none-action"
                        },
                        {
                            "$ref": "#/$defs/shutdown-action"
                        }
                    ]
                }
            },
            "additionalProperties": false
        },
        "all-condition": {
            "type": "object",
            "properties": {
                "all": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "timeout": {
                    "type": "string",
                    "pattern": "^\\d+\\s(milliseconds?|seconds?|minutes?|hours?|days?)$"
                }
            },
            "additionalProperties": false
        },
        "not-all-condition": {
            "type": "object",
            "properties": {
                "not_all": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "timeout": {
                    "type": "string",
                    "pattern": "^\\d+\\s(milliseconds?|seconds?|minutes?|hours?|days?)$"
                }
            },
            "required": [
                "timeout",
                "not_all"
            ],
            "additionalProperties": false
        },
        "any-condition": {
            "type": "object",
            "properties": {
                "any": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            },
            "additionalProperties": false
        },
        "run-playbook-action": {
            "type": "object",
            "properties": {
                "run_playbook": {
                    "type": "object",
                    "properties": {
                        "copy_files": {
                            "type": "boolean"
