                            "type": "integer"
                        },
                        "delay": {
                            "type": "number"
                        },
                        "extra_vars": {
                            "type": "object"
                        }
                    },
                    "required": [
                        "name"
                    ],
                    "additionalProperties": false
                }
            },
            "required": [
                "run_playbook"
            ],
            "additionalProperties": false
        },
        "run-module-action": {
            "type": "object",
            "properties": {
                "run_module": {
                    "type": "object",
                    "properties": {
