			],
			"properties": {
				"git": {
					"$schema": "http://json-schema.org/draft-04/schema#",
					"$ref": "#/definitions/Git"
				},
				"builderImages": {
					"patternProperties": {
						".*": {
							"type": "string"
						}
					},
					"type": "object"
				},
				"buildpacks": {
					"items": {
						"type": "string"
					},
					"type": "array"
				},
				"builder": {
					"enum": [
						"pack",
						"s2i"
					],
					"type": "string"
				},
				"buildEnvs": {
					"items": {
						"$schema": "http://json-schema.org/draft-04/schema#",
