					"type": "array"
				}
			},
			"additionalProperties": false,
			"type": "object"
		},
		"DeploySpec": {
			"required": [
				"namespace",
				"annotations",
				"options",
				"labels",
				"healthEndpoints"
			],
			"properties": {
				"namespace": {
					"type": "string"
				},
				"annotations": {
					"patternProperties": {
						".*": {
							"type": "string"
						}
					},
					"type": "object"
				},
				"options": {
					"$schema": "http://json-schema.org/draft-04/schema#",
					"$ref": "#/definitions/Options"
				},
				"labels": {
					"items": {
						"$schema": "http://json-schema.org/draft-04/schema#",
						"$ref": "#/definitions/Label"
