					"type": "array"
				},
				"healthEndpoints": {
					"$schema": "http://json-schema.org/draft-04/schema#",
					"$ref": "#/definitions/HealthEndpoints"
				}
			},
			"additionalProperties": false,
			"type": "object"
		},
		"Env": {
			"required": [
				"value"
			],
			"properties": {
				"name": {
					"pattern": "^[-._a-zA-Z][-._a-zA-Z0-9]*$",
					"type": "string"
				},
				"value": {
					"type": "string"
				}
			},
			"additionalProperties": false,
			"type": "object"
		},
		"Function": {
			"required": [
				"specVersion",
				"name",
				"runtime",
				"registry",
				"image",
				"imageDigest",
				"created",
				"build",
				"run",
				"deploy"
			],
			"properties": {
				"specVersion": {
					"type": "string"
				},
				"name": {
					"pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$",
					"type": "string"
				},
				"runtime": {
					"type": "string"
				},
				"registry": {
					"type": "string"
				},
				"image": {
					"type": "string"
				},
				"imageDigest": {
					"type": "string"
				},
				"created": {
					"type": "string",
					"format": "date-time"
				},
				"invocation": {
					"$schema": "http://json-schema.org/draft-04/schema#",
					"$ref": "#/definitions/Invocation"
				},
				"build": {
					"$schema": "http://json-schema.org/draft-04/schema#",
					"$ref": "#/definitions/BuildSpec"
				},
				"run": {
					"$schema": "http://json-schema.org/draft-04/schema#",
					"$ref": "#/definitions/RunSpec"
