        "artifactDeployment": {
          "description": "The deployment of artifacts to nexus can be configured with a map containing the following properties.",
          "type": "object",
          "properties": {
            "nexus": {
              "type": "object",
              "properties": {
                "version": {
                  "description": "Version of nexus. Can be nexus2 or nexus3.",
                  "type": "string",
                  "enum": ["nexus2", "nexus3"],
