{
  "$id": "https://json.schemastore.org/codeship-steps.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "ExternalStep": {
      "title": "CodeShip Pro Step",
      "description": "The definition of a step",
      "properties": {
        "name": {
          "description": "The name of the step. Can be omitted.",
          "type": "string"
        },
        "type": {
          "description": "The type of the step. If omitted, defaults to 'run'",
          "type": "string",
          "enum": [null, "run", "serial", "push", "parallel", "load", "manual"]
        },
        "tag": {
          "description": "A pattern matching tags or branches this step and any of its children should be run against. Defaults to always running.",
          "type": "string"
        },
        "exclude": {
          "description": "A pattern matching tags or branches on which this step should NOT be run. Defaults to empty.",
          "type": "string"
        },
        "service": {
          "description": "The service name defined in codeship-services.yml this step will run on",
          "type": "string"
        },
        "services": {
          "description": "A list of service names defined in codeship-services.yml that will be used for this step.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "command": {
          "description": "The command to be run in this step. Required with and can only be used with the 'run' type or no specified type",
          "type": "string"
        },
        "steps": {
          "description": "A list of steps to run within this step or on_fail group. Cannot be used with 'run', 'push', or 'load' steps",
          "items": {
            "$ref": "#/definitions/ExternalStep"
          },
          "type": "array"
        },
        "image_name": {
          "description": "The image name this push step should push to. Required with and only used by the push step",
          "type": "string"
        },
        "image_tag": {
          "description": "The image tag this push step should push to. See https://docs.cloudbees.com/docs/cloudbees-codeship/latest/pro-builds-and-configuration/steps#_push_steps for details. Only used by the push step",
          "default": "latest",
          "type": "string"
        },
        "registry": {
          "description": "The image registry this push step should push to. For Docker Hub, use https://registry-1.docker.io. Required with and only used by the push step",
          "type": "string"
        },
        "encrypted_dockercfg_path": {
          "description": "The location of a Docker configuration file encrypted by Jet to be used with this step. Optional.",
          "type": "string"
        },
        "dockercfg_service": {
          "description": "The name of a service defined in codeship-services.yml that provides the Docker configuration. Optional.",
          "type": "string"
        },
        "on_fail": {
          "description": "An optional list of steps to run if this step fails.",
          "items": {
            "$ref": "#/definitions/ExternalStep"
          },
          "type": "array"
        }
      },
      "if": {
        "properties": {
          "type": {
            "anyOf": [
              {
                "const": "run"
              },
              {
                "type": "null"
              }
            ]
          }
        }
      },
      "then": {
        "properties": {
          "steps": {
            "type": "null"
          },
          "image_name": {
            "type": "null"
          },
          "image_tag": {
            "type": "null"
          },
          "registry": {
            "type": "null"
          }
        },
        "required": ["command"]
      },
      "else": {
        "if": {
          "properties": {
            "type": {
              "const": "push"
            }
          }
        },
        "then": {
          "properties": {
            "command": {
              "type": "null"
            },
            "steps": {
              "type": "null"
            }
          },
          "required": ["image_name", "registry"]
        },
        "else": {
          "if": {
            "properties": {
              "type": {
                "anyOf": [
                  {
                    "const": "serial"
                  },
                  {
                    "const": "parallel"
                  },
                  {
                    "const": "manual"
                  }
                ]
              }
            }
          },
          "then": {
            "properties": {
              "command": {
                "type": "null"
              },
              "image_name": {
                "type": "null"
              },
              "image_tag": {
                "type": "null"
              },
              "registry": {
                "type": "null"
              }
            },
            "required": ["steps"]
          }
        }
      },
      "type": "object",
      "additionalProperties": false
    }
  },
  "description": "codeship-steps.yml is where you configure each step to run in your CI/CD builds with CodeShip.",
  "items": {
    "$ref": "#/definitions/ExternalStep"
  },
  "title": "CodeShip Pro steps configuration",
  "type": "array"
}

{
  "$id": "https://json.schemastore.org/codeship-services.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": {
    "$ref": "#/definitions/ExternalService"
  },
  "definitions": {
    "ExternalService": {
      "title": "CodeShip Pro Service",
      "description": "The definition of a service in a CodeShip Pro build, which can have steps run on it or have other services depend on it",
      "properties": {
        "add_docker": {
          "description": "If true, the docker socket will be exposed in this service.",
          "default": false,
          "type": "boolean"
        },
        "build": {
          "description": "How to build the image for this service. Mutually exclusive with 'image'. Can either be just a path containing a Dockerfile, or a build definition.",
          "oneOf": [
            {
              "$ref": "#/definitions/externalBuild"
            },
            {
              "type": "string"
            }
          ]
        },
        "cached": {
          "description": "Whether the image for this service should be rebuilt from scratch for each run, or if the latest build of the service's image from the configured cache branch (defaulting to 'master') should be used.",
          "default": false,
          "type": "boolean"
        },
        "cap_add": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "cap_drop": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "command": {
          "description": "The command to run when launching the service, overriding the 'CMD' in the image. Optional.",
          "type": "string"
        },
        "cpuset": {
          "type": "string"
        },
        "cpu_shares": {
          "type": "integer"
        },
        "default_cache_branch": {
          "description": "The branch to use for caching. Defaults to 'master'",
          "type": "string"
        },
        "dns": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "dns_search": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "dockercfg_service": {
          "description": "The name of another defined service that provides the Docker configuration for building and running this service. Optional.",
          "type": "string"
        },
        "dockerfile": {
          "description": "A specific Dockerfile to use, rather than the one in the build context",
          "type": "string"
        },
        "domainname": {
          "type": "string"
        },
        "encrypted_dockercfg_path": {
          "description": "The location of a Docker configuration file encrypted by Jet to be used with building and running this service. Optional.",
          "type": "string"
        },
        "encrypted_env_file": {
          "description": "The location of one or more files, encrypted with Jet, containing environment variables to be made available to this service and steps running on it. Optional.",
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "string"
            }
          ]
        },
        "encrypted_environment": {
          "description": "A list of encrypted key/value pairs to be used in the environment for this service and steps running on it. Optional.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "entrypoint": {
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "string"
            }
          ]
        },
        "env_file": {
          "description": "The location of one or more files containing environment variables to be made available to this service and steps running on it. Optional.",
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "string"
            }
          ]
        },
        "environment": {
          "description": "Either a map of key/value pairs or a list of 'KEY=VALUE' pairs to be used in the environment for this service and steps running on it. Optional.",
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "object",
              "additionalProperties": true
            }
          ]
        },
        "expose": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "extra_hosts": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "hostname": {
          "type": "string"
        },
        "image": {
          "description": "A pre-existing image to use for this service. Mutually exclusive with 'build'",
          "type": "string"
        },
        "links": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "depends_on": {
          "description": "A list of other services that this service depends on. Use this instead of 'links'",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "mem_limit": {
          "type": "string"
        },
        "privileged": {
          "type": "boolean"
        },
        "ports": {
          "description": "A list of ports that should be exposed to other services. The ports should be defined like '9999', as strings",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "read_only": {
          "type": "boolean"
        },
        "restart": {
          "type": "string"
        },
        "security_opt": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "user": {
          "type": "string"
        },
        "volumes": {
          "description": "A list of origin/destination pairs of directories or files relative to the build context and where they should be mounted in the service. Optional.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "volumes_from": {
          "description": "A list of other services which should have their defined volumes mounted into this service as well. Optional.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "working_dir": {
          "type": "string"
        }
      },
      "additionalProperties": false,
      "type": "object",
      "oneOf": [
        {
          "required": ["build"]
        },
        {
          "required": ["image"]
        }
      ]
    },
    "externalBuild": {
      "title": "Image Build",
      "description": "Configuration of how to build the image for this service",
      "properties": {
        "path": {
          "description": "DEPRECATED: Use 'context' instead.",
          "type": "string"
        },
        "dockerfile_path": {
          "description": "DEPRECATED: Use 'dockerfile' instead",
          "type": "string"
        },
        "image": {
          "description": "The output image name for this image. Optional.",
          "type": "string"
        },
        "context": {
          "description": "The directory used as the Docker build context. Defaults to the same directory as the codeship-services.yml file",
          "type": "string"
        },
        "dockerfile": {
          "description": "A specific Dockerfile to use rather than the 'Dockerfile' present in the build context. Optional.",
          "type": "string"
        },
        "configure": {
          "$ref": "#/definitions/externalBuildConfigure"
        },
        "args": {
          "description": "Build args to pass to Docker. Optional.",
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "object",
              "additionalProperties": true
            }
          ]
        },
        "encrypted_args_file": {
          "description": "One or more files, encrypted with Jet, to have their contents decrypted and passed to Docker as build args. Optional.",
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "string"
            }
          ]
        },
        "encrypted_args": {
          "description": "A list of encrypted key/value pairs to be used as build args to Docker. Optional.",
          "oneOf": [
            {
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            {
              "type": "string"
            }
          ]
        }
      },
      "additionalProperties": false,
      "type": "object"
    },
    "externalBuildConfigure": {
      "properties": {
        "service": {
          "type": "string"
        },
        "command": {
          "type": "string"
        }
      },
      "additionalProperties": false,
      "type": "object"
    }
  },
  "description": "codeship-services.yml is where you configure each service you need to run your CI/CD builds with CodeShip.",
  "title": "CodeShip Pro services configuration",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": false,
  "definitions": {
    "nonEmptyString": {
      "type": "string",
      "minLength": 1
    },
    "arrayOfNonEmptyStrings": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/definitions/nonEmptyString"
      }
    },
    "nonEmptyStringOrArrayOfNonEmptyStrings": {
      "anyOf": [
        {
          "$ref": "#/definitions/nonEmptyString"
        },
        {
          "$ref": "#/definitions/arrayOfNonEmptyStrings"
        }
      ]
    },
    "webAssemblyFeatures": {
      "type": "string",
      "enum": [
        "sign-extension",
        "mutable-globals",
        "nontrapping-f2i",
        "bulk-memory",
        "simd",
        "threads",
        "exception-handling",
        "tail-calls",
        "reference-types",
        "multi-value",
        "gc",
        "memory64"
      ]
    },
    "compilerOptions": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "optimize": {
          "description": "Optimizes the module.",
          "type": "boolean"
        },
        "optimizeLevel": {
          "description": "How much to focus on optimizing code.",
          "type": "number",
          "minimum": 0,
          "maximum": 3
        },
        "shrinkLevel": {
          "description": "How much to focus on shrinking code size.",
          "type": "number",
          "minimum": 0,
          "maximum": 2
        },
        "converge": {
          "description": "Re-optimizes until no further improvements can be made.",
          "type": "boolean"
        },
        "baseDir": {
          "description": "Specifies the base directory of input and output files.",
          "$ref": "#/definitions/nonEmptyString"
        },
        "outFile": {
          "description": "Specifies the WebAssembly output file (.wasm).",
          "$ref": "#/definitions/nonEmptyString"
        },
        "textFile": {
          "description": "Specifies the WebAssembly text output file (.wat).",
          "$ref": "#/definitions/nonEmptyString"
        },
        "bindings": {
          "description": "Specified the bindings to generate.",
          "definitions": {
            "bindings": {
              "enum": ["esm", "raw"]
            }
          },
          "anyOf": [
            {
              "$ref": "#/definitions/compilerOptions/properties/bindings/definitions/bindings"
            },
            {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "$ref": "#/definitions/compilerOptions/properties/bindings/definitions/bindings"
              }
            }
          ]
        },
        "sourceMap": {
          "description": "Enables source map generation. Optionally takes the URL.",
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "$ref": "#/definitions/nonEmptyString"
            }
          ]
        },
        "runtime": {
          "description": "Specifies the runtime variant to include in the program.",
          "anyOf": [
            {
              "type": "string",
              "enum": ["incremental", "minimal", "stub"]
            },
            {
              "$ref": "#/definitions/nonEmptyString"
            }
          ]
        },
        "noUnsafe": {
          "description": "Disallows the use of unsafe features in user code.",
          "type": "boolean"
        },
        "debug": {
          "description": "Enables debug information in emitted binaries.",
          "type": "boolean"
        },
        "noAssert": {
          "description": "Replaces assertions with just their value without trapping.",
          "type": "boolean"
        },
        "noEmit": {
          "description": "Performs compilation as usual but does not emit code.",
          "type": "boolean"
        },
        "importMemory": {
          "description": "Imports the memory provided as 'env.memory'.",
          "type": "boolean"
        },
        "noExportMemory": {
          "description": "Does not export the memory as 'memory'.",
          "type": "boolean"
        },
        "initialMemory": {
          "description": "Sets the initial memory size in pages.",
          "type": "number"
        },
        "maximumMemory": {
          "description": "Sets the maximum memory size in pages.",
          "type": "number"
        },
        "sharedMemory": {
          "description": "Declare memory as shared. Requires maximumMemory.",
          "type": "number"
        },
        "zeroFilledMemory": {
          "description": "Assume that imported memory is zero filled. Requires importMemory.",
          "type": "boolean"
        },
        "memoryBase": {
          "description": "Sets the start offset of compiler-generated static memory.",
          "type": "number"
        },
        "importTable": {
          "description": "Imports the function table provided as 'env.table'.",
          "type": "boolean"
        },
        "exportTable": {
          "description": "Exports the function table as 'table'.",
          "type": "boolean"
        },
        "exportStart": {
          "description": "Exports the start function instead of calling it implicitly.",
          "$ref": "#/definitions/nonEmptyString"
        },
        "lib": {
          "description": "Adds one or multiple paths to custom library components.",
          "$ref": "#/definitions/nonEmptyStringOrArrayOfNonEmptyStrings"
        },
        "path": {
          "description": "Adds one or multiple paths to package resolution.",
          "$ref": "#/definitions/nonEmptyStringOrArrayOfNonEmptyStrings"
        },
        "use": {
          "description": "Aliases a global object under another name.",
          "$ref": "#/definitions/nonEmptyStringOrArrayOfNonEmptyStrings"
        },
        "trapMode": {
          "description": "Sets the trap mode to use.",
          "type": "string",
          "enum": ["allow", "clamp", "js"]
        },
        "runPasses": {
          "description": "Specifies additional Binaryen passes to run.",
          "$ref": "#/definitions/nonEmptyStringOrArrayOfNonEmptyStrings"
        },
        "noValidate": {
          "description": "Skips validating the module using Binaryen.",
          "type": "boolean"
        },
        "enable": {
          "description": "Enables WebAssembly features that are disabled by default.",
          "anyOf": [
            {
              "$ref": "#/definitions/webAssemblyFeatures"
            },
            {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "$ref": "#/definitions/webAssemblyFeatures"
              }
            }
          ]
        },
        "disable": {
          "description": "Disables WebAssembly features that are enabled by default.",
          "anyOf": [
            {
              "$ref": "#/definitions/webAssemblyFeatures"
            },
            {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "$ref": "#/definitions/webAssemblyFeatures"
              }
            }
          ]
        },
        "transform": {
          "$ref": "#/definitions/nonEmptyStringOrArrayOfNonEmptyStrings",
          "description": "Specifies the path to a custom transform to 'require'."
        },
        "pedantic": {
          "description": "Make yourself sad for no good reason.",
          "type": "boolean"
        },
        "stats": {
          "description": "Prints measuring information on I/O and compile times.",
          "type": "boolean"
        },
        "noColors": {
          "description": "Disables terminal colors.",
          "type": "boolean"
        },
        "exportRuntime": {
          "description": "Exports the runtime helpers (__new, __collect etc.).",
          "type": "boolean"
        },
        "stackSize": {
          "description": "Exports the runtime helpers (__new, __collect etc.).",
          "type": "number",
          "minimum": 0
        },
        "lowMemoryLimit": {
          "description": "Enforces very low (<64k) memory constraints.",
          "type": "number",
          "minimum": 0
        },
        "tableBase": {
          "description": "Sets the start offset of emitted table elements.",
          "type": "number",
          "minimum": 0
        },
        "wasm": {
          "description": "Uses the specified Wasm binary of the compiler.",
          "$ref": "#/definitions/nonEmptyString"
        }
      }
    }
  },
  "id": "https://json.schemastore.org/asconfig-schema.json",
  "properties": {
    "extends": {
      "$ref": "#/definitions/nonEmptyString"
    },
    "entries": {
      "$ref": "#/definitions/arrayOfNonEmptyStrings"
    },
    "options": {
      "$ref": "#/definitions/compilerOptions"
    },
    "targets": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/compilerOptions"
      }
    }
  },
  "title": "JSON schema for asconfig.json",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "description": "JSON Schema for Grafana 5.x Dashboards (https://grafana.com/docs/grafana/latest/reference/dashboard/#dashboard-json)",
  "id": "https://json.schemastore.org/grafana-dashboard-5.x.json",
  "properties": {
    "meta": {
      "type": "object",
      "properties": {
        "isStarred": {
          "type": "boolean"
        }
      }
    },
    "dashboard": {
      "type": "object",
      "properties": {
        "id": {
          "description": "unique numeric identifier for the dashboard. (generated by the db)",
          "type": ["number", "null"]
        },
        "uid": {
          "description": "unique dashboard identifier that can be generated by anyone. string (8-40)",
          "type": "string",
          "minLength": 8,
          "maxLength": 40
        },
        "title": {
          "description": "current title of dashboard",
          "type": "string"
        },
        "tags": {
          "description": "tags associated with dashboard, an array of strings",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "style": {
          "description": "theme of dashboard, i.e. dark or light",
          "type": "string"
        },
        "timezone": {
          "description": "timezone of dashboard, i.e. utc or browser",
          "type": "string"
        },
        "editable": {
          "description": "whether a dashboard is editable or not",
          "type": "boolean"
        },
        "hideControls": {
          "type": "boolean"
        },
        "graphTooltip": {
          "description": "0 for no shared crosshair or tooltip (default), 1 for shared crosshair, 2 for shared crosshair AND shared tooltip",
          "type": "number",
          "minimum": 0,
          "maximum": 2
        },
        "panels": {
          "description": "Panels are the building blocks of a dashboard. It consists of data source queries, type of graphs, aliases, etc. Panel JSON consists of an array of JSON objects, each representing a different panel. Most of the fields are common for all panels but some fields depend on the panel type.",
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "type": {
                "type": "string"
              },
              "title": {
                "type": "string"
              },
              "gridPos": {
                "description": "The gridPos property describes the panel size and position in grid coordinates.",
                "type": "object",
                "properties": {
                  "x": {
                    "description": "The x position, in same unit as w.",
                    "type": "number"
                  },
                  "y": {
                    "description": "The y position, in same unit as h.",
                    "type": "number"
                  },
                  "w": {
                    "description": "1-24 (the width of the dashboard is divided into 24 columns)",
                    "type": "number",
                    "minimum": 1,
                    "maximum": 24
                  },
                  "h": {
                    "description": "In grid height units, each represents 30 pixels.",
                    "type": "number"
                  }
                }
              },
              "id": {
                "type": "number"
              },
              "mode": {
                "type": "string"
              },
              "content": {
                "type": "string"
              }
            }
          }
        },
        "time": {
          "description": "time range for dashboard, i.e. last 6 hours, last 7 days, etc"
        },
        "timepicker": {
          "description": "timepicker metadata",
          "type": "object",
          "properties": {
            "collapse": {
              "description": "whether timepicker is collapsed or not",
              "type": "boolean"
            },
            "enable": {
              "description": "whether timepicker is enabled or not",
              "type": "boolean"
            },
            "notice": {
              "type": "boolean"
            },
            "now": {
              "type": "boolean"
            },
            "refresh_intervals": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "status": {
              "type": "string"
            },
            "type": {
              "type": "string"
            }
          }
        },
        "templating": {
          "description": "templating metadata",
          "type": "object",
          "properties": {
            "enable": {
              "description": "whether templating is enabled or not",
              "type": "boolean"
            },
            "list": {
              "description": "an array of objects each representing one template variable",
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "allFormat": {
                    "description": "format to use while fetching all values from data source, eg: wildcard, glob, regex, pipe, etc.",
                    "type": "string"
                  },
                  "current": {
                    "description": "shows current selected variable text/value on the dashboard",
                    "type": "object",
                    "properties": {
                      "tags": {
                        "type": "array",
                        "items": {
                          "type": "string"
                        }
                      },
                      "text": {
                        "type": "string"
                      },
                      "value": {
                        "type": "string"
                      }
                    }
                  },
                  "datasource": {
                    "description": "shows data source for the variables",
                    "type": ["string", "null"]
                  },
                  "includeAll": {
                    "description": "whether all value option is available or not",
                    "type": "boolean"
                  },
                  "multi": {
                    "description": "whether multiple values can be selected or not from variable value list",
                    "type": "boolean"
                  },
                  "multiFormat": {
                    "description": "format to use while fetching timeseries from data source",
                    "type": "string"
                  },
                  "name": {
                    "description": "name of variable",
                    "type": "string"
                  },
                  "options": {
                    "description": "array of variable text/value pairs available for selection on dashboard",
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "selected": {
                          "type": "boolean"
                        },
                        "text": {
                          "type": "string"
                        },
                        "value": {
                          "type": "string"
                        }
                      }
                    }
                  },
                  "query": {
                    "description": "data source query used to fetch values for a variable",
                    "type": "string"
                  },
                  "refresh": {
                    "type": "boolean"
                  },
                  "regex": {
                    "type": "string"
                  },
                  "type": {
                    "description": "type of variable, i.e. custom, query or interval",
                    "type": "string"
                  }
                }
              }
            }
          }
        },
        "annotations": {
          "description": "annotations metadata"
        },
        "refresh": {
          "description": "auto-refresh interval"
        },
        "schemaVersion": {
          "description": "version of the JSON schema (integer), incremented each time a Grafana update brings changes to said schema",
          "type": "number"
        },
        "version": {
          "description": "version of the dashboard (integer), incremented each time the dashboard is updated",
          "type": "number",
          "minimum": 1
        },
        "links": {}
      }
    },
    "overwrite": {
      "type": "boolean"
    }
  },
  "title": "Grafana Dashboard 5.x",
  "type": "object"
}

{
    "title": "JSON Schema for Beef Entity code-generation (https://github.com/Avanade/Beef).",
    "$schema": "http://json-schema.org/draft-04/schema",
    "definitions": {
        "CodeGeneration": {
            "type": "object",
            "title": "'CodeGeneration' object (entity-driven)",
            "description": "The 'CodeGeneration' object defines global properties that are used to drive the underlying entity-driven code generation.",
            "properties": {
                "refDataNamespace": {
                    "type": "string",
                    "title": "The namespace for the Reference Data entities (adds as a c# 'using' statement).",
                    "description": "Defaults to 'Company' + '.' (literal) + AppName + '.' (literal) + 'EntityUsing' + '.Entities' (literal)."
                },
                "refDataCommonNamespace": {
                    "type": "string",
                    "title": "The namespace for the Reference Data common entities (adds as a c# 'using' statement).",
                    "description": "Defaults to 'Company' + '.' (literal) + AppName + '.Common.Entities' (literal)."
                },
                "refDataText": {
                    "type": "boolean",
                    "title": "Indicates whether a corresponding 'Text' property is added when generating a Reference Data 'Property' for an 'Entity'.",
                    "description": "This is used where serializing within the Web API 'Controller' and the 'ExecutionContext.IsRefDataTextSerializationEnabled' is set to 'true' (which is automatically set where the url contains '$text=true')."
                },
                "refDataWebApiRoute": {
                    "type": "string",
                    "title": "The 'RouteAtttribute' for the Reference Data Web API controller required for named pre-fetching. The 'WebApiRoutePrefix' will be prepended where specified."
                },
                "refDataCache": {
                    "type": "string",
                    "title": "The cache used for the ReferenceData providers.",
                    "description": "Defaults to 'ReferenceDataCache'. A value of 'ReferenceDataCache' specifies a single-tenant cache; otherwise, 'ReferenceDataMultiTenantCache' for a multi-tenant cache leverageing the 'ExecutionContext.TenantId'.",
                    "enum": [
                        "ReferenceDataCache",
                        "ReferenceDataMultiTenantCache"
                    ]
                },
                "refDataAppendToNamespace": {
                    "type": "string",
                    "title": "The Reference Data entity namespace appended to end of the standard 'company.appname.Common.Entities.{AppendToNamespace}'.",
                    "description": "Defaults to 'null'; being nothing to append."
                },
                "refDataBusNamespace": {
                    "type": "string",
                    "title": "The namespace for the Reference Data entities (adds as a c# 'using' statement) for additional business-layer inclusion where requried."
                },
                "entityScope": {
                    "type": "string",
                    "title": "The entity scope option.",
                    "description": "Defaults to 'Common' for backwards compatibility; 'Autonomous' is **recommended**. Determines where the entity is scoped/defined, being 'Common' or 'Business' (i.e. not externally visible). Additionally, there is the special case of 'Autonomous' where both a 'Common' and 'Business' entity are generated (where only the latter inherits from 'EntityBase', etc).",
                    "enum": [
                        "Common",
                        "Business",
                        "Autonomous"
                    ]
                },
                "entityUsing": {
                    "type": "string",
                    "title": "The namespace for the non Reference Data entities (adds as a c# <c>using</c> statement).",
                    "description": "Defaults to 'Common' (unless 'EntityScope' is 'Autonomous' and then it will default to 'Business') which will add '.Common.Entities'. Additionally, 'Business' to add '.Business.Entities', 'All' to add both, and 'None' to exclude any. This can be overridden for each 'Entity'.",
                    "enum": [
                        "Common",
                        "Business",
                        "All",
                        "None"
                    ]
                },
                "jsonSerializer": {
                    "type": "string",
                    "title": "The JSON Serializer to use for JSON property attribution.",
                    "description": "Defaults to 'Newtonsoft'. This can be overridden within the 'Entity'(s).",
                    "enum": [
                        "None",
                        "Newtonsoft"
                    ]
                },
                "etagJsonName": {
                    "type": "string",
                    "title": "The default JSON name for the 'ETag' property.",
                    "description": "Defaults to 'etag'. Note that the 'JsonName' can be set individually per property where required.",
                    "enum": [
                        "etag",
                        "eTag",
                        "_etag",
                        "_eTag",
                        "ETag",
                        "ETAG"
                    ]
                },
                "usingNamespace1": {
                    "type": "string",
                    "title": "The additional Namespace using statement to be added to the generated 'Entity' code.",
                    "description": "Typically used where referening a 'Type' from a Namespace that is not generated by default."
                },
                "usingNamespace2": {
                    "type": "string",
                    "title": "The additional Namespace using statement to be added to the generated 'Entity' code.",
                    "description": "Typically used where referening a 'Type' from a Namespace that is not generated by default."
                },
                "usingNamespace3": {
                    "type": "string",
                    "title": "The additional Namespace using statement to be added to the generated 'Entity' code.",
                    "description": "Typically used where referening a 'Type' from a Namespace that is not generated by default."
                },
                "webApiAuthorize": {
                    "type": "string",
                    "title": "The authorize attribute value to be used for the corresponding entity Web API controller; generally either 'Authorize' or 'AllowAnonymous'.",
                    "description": "This can be overridden within the 'Entity'(s) and/or their corresponding 'Operation'(s)."
                },
                "appBasedAgentArgs": {
                    "type": "boolean",
                    "title": "Indicates whether to create and use a domain-specific 'WebApi.WebApiAgentArgs' to simplify dependency injection usage."
                },
                "webApiAutoLocation": {
                    "type": "boolean",
                    "title": "Indicates whether the HTTP Response Location Header route ('Operation.WebApiLocation') is automatically inferred.",
                    "description": "This will automatically set the 'Operation.WebApiLocation' for an 'Operation' named 'Create' where there is a corresponding named 'Get'. This can be overridden within the 'Entity'(s)."
                },
                "webApiRoutePrefix": {
                    "type": "string",
                    "title": "The 'RoutePrefixAtttribute' for the corresponding entity Web API controller.",
                    "description": "This is the base (prefix) 'URI' prepended to all entity and underlying 'Operation'(s)."
                },
                "validatorLayer": {
                    "type": "string",
                    "title": "The namespace for the Reference Data entities (adds as a c# 'using' statement).",
                    "description": "Defaults to 'Business'. A value of 'Business' indicates that the Validators will be defined within the 'Business' namespace/assembly; otherwise, defined within the 'Common' namespace/assembly.",
                    "enum": [
                        "Business",
                        "Common"
                    ]
                },
                "databaseName": {
                    "type": "string",
                    "title": "The .NET database interface name (used where 'Operation.AutoImplement' is 'Database').",
                    "description": "Defaults to 'IDatabase'. This can be overridden within the 'Entity'(s)."
                },
                "databaseSchema": {
                    "type": "string",
                    "title": "The default database schema name.",
                    "description": "Defaults to 'dbo'."
                },
                "entityFrameworkName": {
                    "type": "string",
                    "title": "The .NET Entity Framework interface name used where 'Operation.AutoImplement' is 'EntityFramework'.",
                    "description": "Defaults to 'IEfDb'. This can be overridden within the 'Entity'(s)."
                },
                "cosmosName": {
                    "type": "string",
                    "title": "The .NET Entity Framework interface name used where 'Operation.AutoImplement' is 'Cosmos'.",
                    "description": "Defaults to 'ICosmosDb'. This can be overridden within the 'Entity'(s)."
                },
                "odataName": {
                    "type": "string",
                    "title": "The .NET OData interface name used where 'Operation.AutoImplement' is 'OData'.",
                    "description": "Defaults to 'IOData'. This can be overridden within the 'Entity'(s)."
                },
                "httpAgentName": {
                    "type": "string",
                    "title": "The default .NET HTTP Agent interface name used where 'Operation.AutoImplement' is 'HttpAgent'.",
                    "description": "Defaults to 'IHttpAgent'. This can be overridden within the 'Entity'(s)."
                },
                "refDataDefaultMapperConverter": {
                    "type": "string",
                    "title": "The default Reference Data property 'Converter' used by the generated 'Mapper'(s) where not specifically defined.",
                    "description": "Defaults to 'ReferenceDataCodeConverter<T>'. Where this value is suffixed by '<T>' or '{T}' this will automatically set 'Property.DataConverterIsGeneric' to 'true'.",
                    "enum": [
                        "ReferenceDataCodeConverter",
                        "ReferenceDataCodeConverter{T}",
                        "ReferenceDataCodeConverter<T>",
                        "ReferenceDataInt32IdConverter",
                        "ReferenceDataInt32IdConverter{T}",
                        "ReferenceDataInt32IdConverter<T>",
                        "ReferenceDataNullableInt32IdConverter",
                        "ReferenceDataNullableInt32IdConverter{T}",
                        "ReferenceDataNullableInt32IdConverter<T>",
                        "ReferenceDataInt64IdConverter",
                        "ReferenceDataInt64IdConverter{T}",
                        "ReferenceDataInt64IdConverter<T>",
                        "ReferenceDataNullableInt64IdConverter",
                        "ReferenceDataNullableInt64IdConverter{T}",
                        "ReferenceDataNullableInt64IdConverter<T>",
                        "ReferenceDataGuidIdConverter",
                        "ReferenceDataGuidIdConverter{T}",
                        "ReferenceDataGuidIdConverter<T>",
                        "ReferenceDataNullableGuidIdConverter",
                        "ReferenceDataNullableGuidIdConverter{T}",
                        "ReferenceDataNullableGuidIdConverter<T>"
                    ]
                },
                "dataUsingNamespace": {
                    "type": "string",
                    "title": "The additional Namespace using statement to be added to the generated 'Data' code."
                },
                "databaseUsingNamespace": {
                    "type": "string",
                    "title": "The additional Namespace using statement to be added to the generated 'Data' code where 'Operation.AutoImplement' is 'Database'."
                },
                "entityFrameworkUsingNamespace": {
                    "type": "string",
                    "title": "The additional Namespace using statement to be added to the generated 'Data' code where 'Operation.AutoImplement' is 'EntityFramework'."
                },
                "cosmosUsingNamespace": {
                    "type": "string",
                    "title": "additional Namespace using statement to be added to the generated 'Data' code where 'Operation.AutoImplement' is 'Cosmos'."
                },
                "odataUsingNamespace": {
                    "type": "string",
                    "title": "additional Namespace using statement to be added to the generated 'Data' code where 'Operation.AutoImplement' is 'OData'."
                },
                "eventPublish": {
                    "type": "string",
                    "title": "The layer to add logic to publish an event for a 'Create', 'Update' or 'Delete' operation.",
                    "description": "Defaults to 'DataSvc'; unless the 'EventOutbox' is not 'None' where it will default to 'Data'. Used to enable the sending of messages to the likes of EventHub, Service Broker, SignalR, etc. This can be overridden within the 'Entity'(s).",
                    "enum": [
                        "None",
                        "DataSvc",
                        "Data"
                    ]
                },
                "eventOutbox": {
                    "type": "string",
                    "title": "The the data-tier event outbox persistence technology (where the events will be transactionally persisted in an outbox as part of the data-tier processing).",
                    "description": "Defaults to 'None'. A value of 'Database' will result in the 'DatabaseEventOutboxInvoker' being used to orchestrate.",
                    "enum": [
                        "None",
                        "Database"
                    ]
                },
                "eventSourceRoot": {
                    "type": "string",
                    "title": "The URI root for the event source by prepending to all event source URIs.",
                    "description": "The event source is only updated where an 'EventSourceKind' is not 'None'. This can be extended within the 'Entity'(s)."
                },
                "eventSourceKind": {
                    "type": "string",
                    "title": "The URI kind for the event source URIs.",
                    "description": "Defaults to 'None' (being the event source is not updated).",
                    "enum": [
                        "None",
                        "Absolute",
                        "Relative",
