      },
      "description": "Mount [persistent storage volumes](https://fly.io/docs/reference/volumes) previously setup via `flyctl`. Both settings are required. Example:\n\n```toml\n[mounts]\n  source = \"myapp_data\"\n  destination = \"/data\"\n```",
      "required": ["source", "destination"],
      "additionalProperties": false,
      "properties": {
        "source": {
          "description": "The name of the volume to mount as shown in `fly volumes list`.\n\nA volume of this name *must exist* in each of the app regions. If there's more than one volume in the target region with the same one, one will be picked randomly.",
          "type": "string"
        },
        "destination": {
          "description": "The path at which the `source` volume should be mounted in the running app VM.",
          "type": "string"
        },
        "processes": {
          "description": "The name of the process(es) to which this mount should be applied. See [multiple processes](https://community.fly.io/t/preview-multi-process-apps-get-your-workers-here/2316).",
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "experimental": {
      "description": "Flags and features that are subject to change, deprecation or promotion to the main configuration.",
      "type": "object",
      "properties": {
        "cmd": {
          "description": "Override the server command (CMD) set by the Dockerfile. Specify as an array of strings:\n\n```toml\ncmd = [\"path/to/command\", \"arg1\", \"arg2\"]\n```",
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "entrypoint": {
          "description": "Override the ENTRYPOINT set by the Dockerfile. Specify as an array of strings:\n\n```toml\nentrypoint = [\"path/to/command\", \"arg1\", \"arg2\"]\n```",
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ]
        },
        "auto_rollback": {
          "description": "Failed deployments should roll back automatically to the previous successfully deployed release. Defaults to `true`",
          "type": "boolean"
        },
        "private_network": {
          "description": "Enables private network access to the Fly organization. Defaults to `true`.",
          "default": true,
          "type": "boolean"
        }
      }
    },
    "env": {
      "description": "Set non-sensitive information as environment variables in the application's [runtime environment](https://fly.io/docs/reference/runtime-environment/).\nFor sensitive information, such as credentials or passwords, use the [secrets command](https://fly.io/docs/reference/secrets). For anything else though, the `env` section provides a simple way to set environment variables. Here's an example:\n```toml\n[env]\n  LOG_LEVEL = \"debug\"\n  S3_BUCKET = \"my-bucket\"\n```",
      "type": "object",
      "additionalProperties": {
        "type": "string"
      }
    },
    "build": {
      "description": "Build configuration options. See docs at https://fly.io/docs/reference/builders.",
      "type": "object",
      "properties": {
        "builder": {
          "description": "Builder Docker image to be used with the 'buildpacks' option",
          "type": "string"
        },
        "buildpacks": {
          "description": "Buildpacks to be run by the 'builder' Docker image",
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "uniqueItems": true,
          "minItems": 1
        },
        "args": {
          "description": "Build arguments passed to both Dockerfile and Buildpack builds. These arguments are **not available** on VMs at runtime.\n```toml\n[build.args]\n  USER = \"julieta\"\n  MODE = \"production\"\n```",
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "build-target": {
          "description": "Specify the target stage for [multistage Dockerfile builds](https://docs.docker.com/develop/develop-images/multistage-build/).",
          "type": "string"
        },
        "image": {
          "description": "Docker image to be deployed (skips the build process)",
          "type": "string"
        },
        "dockerfile": {
          "description": "Dockerfile used for builds. Defaults to './Dockerfile'",
          "type": "string"
        },
        "additionalProperties": false
      }
    },
    "additionalProperties": true
  },
  "title": "Fly.io config schema (fly.toml)",
  "type": "object",
  "x-taplo-info": {
    "authors": ["Joshua Sierles (https://github.com/jsierles)"],
    "patterns": ["\\.*fly(.*)?\\.toml?$"]
  }
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"$id": "http://github.com/ray-project/ray/python/ray/autoscaler/ray-schema.json",
	"title": "Ray AutoScaler",
	"description": "Ray autoscaler schema",
	"type": "object",
	"definitions": {
        "commands": {
            "type": "array",
            "items": {
                "type": "string",
                "description": "shell command"
            }
        }
    },
    "required": [
        "cluster_name",
        "provider"
    ],
    "additionalProperties": false,
	"properties": {
        "cluster_name": {
            "description": "A unique identifier for the head node and workers of this cluster.",
            "type": "string"
        },
        "max_workers": {
            "description": "The maximum number of workers nodes to launch in addition to the head node. This takes precedence over min_workers.",
            "type": "integer",
            "minimum": 0
        },
        "upscaling_speed": {
            "description": "The autoscaler will scale up the cluster faster with higher upscaling speed. E.g., if the task requires adding more nodes then autoscaler will gradually scale up the cluster in chunks of upscaling_speed*currently_running_nodes. This number should be > 0.",
            "type": "number",
            "minimum": 0
        },
        "idle_timeout_minutes": {
            "description": "If a node is idle for this many minutes, it will be removed.",
            "type": "number",
            "minimum": 0
        },
        "provider": {
            "type": "object",
            "description": "Cloud-provider specific configuration.",
            "required": [ "type" ],
            "additionalProperties": true,
            "properties": {
                "type": {
                    "type": "string",
                    "description": "e.g. aws, azure, gcp,..."
                },
                "region": {
                    "type": "string",
                    "description": "e.g. us-east-1"
                },
                "module": {
                    "type": "string",
                    "description": "module, if using external node provider"
                },
                "head_ip": {
                    "type": "string",
                    "description": "gcp project id, if using gcp"
                },
                "worker_ips": {
                    "type": "array",
                    "description": "local cluster head node"
                },
                "use_internal_ips": {
                    "type": "boolean",
                    "description": "don't require public ips"
                },
                "namespace": {
                    "type": "string",
                    "description": "k8s namespace, if using k8s"
                },
                "location": {
                    "type": "string",
                    "description": "Azure location"
                },
                "resource_group": {
                    "type": "string",
                    "description": "Azure resource group"
                },
                "tags": {
                    "type": "object",
                    "description": "Azure user-defined tags"
                },
                "subscription_id": {
                    "type": "string",
                    "description": "Azure subscription id"
                },
                "msi_identity_id": {
                    "type": "string",
                    "description": "User-defined managed identity (generated by config)"
                },
                "msi_identity_principal_id": {
                    "type": "string",
                    "description": "User-defined managed identity principal id (generated by config)"
                },
                "subnet_id": {
                    "type": "string",
                    "description": "Network subnet id"
                },
                "autoscaler_service_account": {
                    "type": "object",
                    "description": "k8s autoscaler permissions, if using k8s"
                },
                "autoscaler_role": {
                    "type": "object",
                    "description": "k8s autoscaler permissions, if using k8s"
                },
                "autoscaler_role_binding": {
                    "type": "object",
                    "description": "k8s autoscaler permissions, if using k8s"
                },
                "cache_stopped_nodes": {
                    "type": "boolean",
                    "description": " Whether to try to reuse previously stopped nodes instead of launching nodes. This will also cause the autoscaler to stop nodes instead of terminating them. Only implemented for AWS."
                },
                "availability_zone": {
                    "type": "string",
                    "description": "GCP availability zone"
                },
                "project_id": {
                    "type": ["string", "null"],
                    "description": "GCP globally unique project id"
                },
                "security_group": {
                    "type": "object",
                    "description": "AWS security group",
                    "additionalProperties": false,
                    "properties": {
                      "GroupName": {
                        "type": "string",
                        "description": "Security group name"
                      },
                      "IpPermissions": {
                        "type": "array",
                        "description": "Security group in bound rules"
                      }
                    }
                },
				"disable_node_updaters": {
					"type": "boolean",
					"description": "Disables node updaters if set to True. Default is False. (For Kubernetes operator usage.)"
				},
                "gcp_credentials": {
                    "type": "object",
                    "description": "Credentials for authenticating with the GCP client",
                    "required": [ "type" ],
                    "additionalProperties": false,
                    "properties": {
                        "type": {
                            "type": "string",
                            "enum": ["credentials_token", "service_account"],
                            "description": "Credentials type: either temporary OAuth 2.0 token or permanent service account credentials blob."
                        },
                        "credentials": {
                            "type": "string",
                            "description": "Oauth token or JSON string constituting service account credentials"
                        }
                    }
                },
                "cloudwatch": {
                    "agent": {
                        "CLOUDWATCH_AGENT_INSTALLED_AMI_TAG": {
                            "type": ["string"],
                            "description": "Tag to be added to cloudwatch agent pre-installed AMI name."
                        },
                        "config": {
                            "type": ["string", "null"],
                            "description": "Path to Unified CloudWatch Agent config file. See https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/CloudWatch-Agent-Configuration-File-Details.html for additional details."
                        },
                        "retryer": {
                            "max_attempts": {
                                "type": ["integer", "null"],
                                "description": "Max allowed Unified CloudWatch Agent installation attempts on any host."
                            },
                            "delay_seconds": {
                                "type": ["integer", "null"],
                                "description": "Seconds to wait between each Unified CloudWatch Agent installation attempt."
                            }
                        }
                    },
                    "dashboard": {
                        "name": {
                            "type": ["string", "null"],
                            "description": "User defined CloudWatch Dashboard name."
                        },
                        "config": {
                            "type": ["string", "null"],
                            "description": "Path to CloudWatch Dashboard config file. See https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/CloudWatch-Dashboard-Body-Structure.html for additional details."
                        }
                    },
                    "alarm": {
                        "config": {
                            "type": ["string", "null"],
                            "description": "Path to CloudWatch Alarm config file. See https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_PutMetricAlarm.html for additional details."
                        }
                    }
                }
            }
        },
        "auth": {
            "type": "object",
            "description": "How Ray will authenticate with newly launched nodes.",
            "additionalProperties": false,
            "properties": {
                "ssh_user": {
                    "type": "string",
                    "default": "ubuntu"
                },
                "ssh_public_key": {
                    "type": "string"
                },
                "ssh_private_key": {
                    "type": "string"
                },
                "ssh_proxy_command": {
                    "description": "A value for ProxyCommand ssh option, for connecting through proxies. Example: nc -x proxy.example.com:1234 %h %p",
                    "type": "string"
                }
            }
        },
        "docker": {
            "type": "object",
            "description": "Docker configuration. If this is specified, all setup and start commands will be executed in the container.",
            "additionalProperties": false,
            "properties": {
                "image": {
                    "type": "string",
                    "description": "the docker image name",
                    "default": "rayproject/ray:latest"
                },
                "container_name": {
                    "type": "string",
                    "default": "ray_docker"
                },
                "pull_before_run": {
                    "type": "boolean",
                    "description": "run `docker pull` first"
                },
                "run_options": {
                    "type": "array",
                    "description": "shared options for starting head/worker docker"
                },
                "head_image": {
                    "type": "string",
                    "description": "image for head node, takes precedence over 'image' if specified"
                },
                "head_run_options": {
                    "type": "array",
                    "description": "head specific run options, appended to run_options"
                },
                "worker_image": {
                    "type": "string",
                    "description": "analogous to head_image"
                },
                "worker_run_options": {
                    "type": "array",
                    "description": "analogous to head_run_options"
                },
                "disable_automatic_runtime_detection" : {
                    "type": "boolean",
                    "description": "disable Ray from automatically using the NVIDIA runtime if available",
                    "default": false
                },
                "disable_shm_size_detection" : {
                    "type": "boolean",
                    "description": "disable Ray from automatically detecting /dev/shm size for the container",
                    "default": false
                },
              "use_podman"  :  {
                "type": "boolean",
                "description": "Use 'podman' command in place of 'docker'",
                "default": false
                }
            }
        },
        "head_node_type": {
            "type": "string",
            "description": "If using multiple node types, specifies the head node type."
        },
        "file_mounts": {
            "type": "object",
            "description": "Map of remote paths to local paths, e.g. {\"/tmp/data\": \"/my/local/data\"}"
        },
        "cluster_synced_files": {
            "type": "array",
            "description": "List of paths on the head node which should sync to the worker nodes, e.g. [\"/some/data/somehwere\"]"
        },
        "file_mounts_sync_continuously": {
            "type": "boolean",
            "description": "If enabled, file mounts will sync continously between the head node and the worker nodes. The nodes will not re-run setup commands if only the contents of the file mounts folders change."
        },
        "rsync_exclude": {
            "type": "array",
            "description": "File pattern to not sync up or down when using the rsync command. Matches the format of rsync's --exclude param."
        },
        "rsync_filter": {
            "type": "array",
            "description": "Pattern files to lookup patterns to exclude when using rsync up or rsync down. This file is checked for recursively in all directories. For example, if .gitignore is provided here, the behavior will match git's .gitignore behavior."
        },
        "metadata": {
            "type": "object",
            "description": "Metadata field that can be used to store user-defined data in the cluster config. Ray does not interpret these fields."
        },
        "initialization_commands": {
            "$ref": "#/definitions/commands",
            "description": "List of commands that will be run before `setup_commands`. If docker is enabled, these commands will run outside the container and before docker is setup."
        },
        "setup_commands": {
            "$ref": "#/definitions/commands",
            "description": "List of common shell commands to run to setup nodes."
        },
        "head_setup_commands": {
            "$ref": "#/definitions/commands",
            "description": "Commands that will be run on the head node after common setup."
        },
        "worker_setup_commands": {
            "$ref": "#/definitions/commands",
            "description": "Commands that will be run on worker nodes after common setup."
        },
        "head_start_ray_commands": {
            "$ref": "#/definitions/commands",
            "description": "Command to start ray on the head node. You shouldn't need to modify this."
        },
        "worker_start_ray_commands": {
            "$ref": "#/definitions/commands",
            "description": "Command to start ray on worker nodes. You shouldn't need to modify this."
        },
        "no_restart": {
            "description": "Whether to avoid restarting the cluster during updates. This field is controlled by the ray --no-restart flag and cannot be set by the user."
        },
        "available_node_types": {
            "type": "object",
            "description": "A list of node types for multi-node-type autoscaling.",
            "patternProperties": {
                ".*": {
                    "type": "object",
                    "required": [ "resources", "node_config" ],
                    "properties": {
                       "node_config": {
                           "type": "object",
                           "description": "Provider-specific config for the node, e.g. instance type."
                       },
                       "min_workers": {"type": "integer"},
                       "max_workers": {"type": "integer"},
                       "resources": {
						   "type": "object",
						   "patternProperties": {
							   ".*":{
								   "type": "integer",
								   "minimum": 0
							   }
						   }
                       },
                       "labels": {
						   "type": "object",
						   "patternProperties": {
							   ".*":{
								   "type": "string"
							   }
						   }
                       },
                       "initialization_commands": {
                           "$ref": "#/definitions/commands",
                           "description": "List of commands that will be run before `setup_commands`. If docker is enabled, these commands will run outside the container and before docker is setup."
                       },
                       "worker_setup_commands": {
                           "$ref": "#/definitions/commands",
                           "description": "List of common shell commands to run to setup nodes. This node specfic list will override the global setup_commands and worker_setup_commands."
                       },
                       "docker": {
                        "description": "Configuration of Worker nodes.",
                        "type": "object",
                        "properties": {
                            "pull_before_run": {
                                "type": "boolean",
                                "description": "run `docker pull` first"
                            },
                            "worker_image": {
                                "type": "string",
                                "description": "analogous to head_image"
                            },
                            "worker_run_options": {
                                "type": "array",
                                "description": "analogous to head_run_options, merged with the global docker run_options."
                            }
                        },
                        "additionalProperties": false
                    }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false
        }
    }
}

{
  "$defs": {},
  "$id": "https://json.schemastore.org/clang-format.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": {},
  "description": "The .clang-format file is a YAML file defining formatting styles used by clang-format.\r\r see https://clang.llvm.org/docs/ClangFormatStyleOptions.html",
  "patternProperties": {
    "^x-": {
      "$comment": "yaml marker for multiple documents in one single yaml file"
    }
  },
  "properties": {
    "BasedOnStyle": {
      "$comment": "clang-format ignores cases. For the sake of consistency, use one of following enums",
      "description": "The style used for all options not specifically set in the configuration.",
      "type": "string",
      "enum": [
        "Chromium",
        "Google",
        "LLVM",
        "Mozilla",
        "WebKit",
        "Microsoft",
        "GNU",
        "InheritParentConfig",
        "chromium",
        "google",
        "llvm",
        "mozilla",
        "webkit",
        "microsoft",
        "gnu",
        "inheritparentconfig"
      ]
    },
    "AccessModifierOffset": {
      "description": "clang-format 3.3\r\r The extra indent or outdent of access modifiers, e.g. public:.",
      "type": "integer"
    },
    "AlignAfterOpenBracket": {
      "description": "clang-format 3.8\r\r This applies to round brackets (parentheses), angle brackets and square brackets.",
      "type": "string",
      "enum": ["Align", "DontAlign", "AlwaysBreak", "BlockIndent"]
    },
    "AlignArrayOfStructures": {
      "description": "clang-format 13\r\r if not None, when using initialization for an array of structs aligns the fields into columns.\r\r NOTE: In clang-format 15 this option only applied to arrays with equal number of columns per row.",
      "type": "string",
      "enum": ["None", "Left", "Right"]
    },
    "AlignConsecutiveMacros": {
      "oneOf": [
        {
          "description": "clang-format 9\r\r Style of aligning consecutive macros.",
          "type": "string",
          "enum": [
            "None",
            "Consecutive",
            "AcrossEmptyLines",
            "AcrossComments",
            "AcrossEmptyLinesAndComments"
          ]
        },
        {
